window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-25"]={"date":"2026-06-25","dateKR":"2026년 6월 25일","dateEN":"25 June 2026","total":169,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. Top News","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"호르무즈 통항 급반등…미·이란 합의 후 유조선 운항 재개","src":"CNBC","date":"2026-06-19","kSum":"6월 18일 미국과 이란이 호르무즈 해협 상업항행 정상화에 합의하면서, 19일 하루에만 최소 20척의 유조선이 통항해 6월 2일 이후 최대치를 기록했다. 사우디 VLCC 3척이 AIS를 재가동하며 오만만으로 진입했다.","eSum":"After the 18 June US-Iran navigation deal, at least 20 tankers transited Hormuz on the 19th - the most since 2 June - and three Saudi VLCCs reactivated AIS in the Gulf of Oman.","kImp":"원유 톤마일과 탱커 운임에 직접 영향을 주는 핵심 변수다.","eImp":"A pivotal swing factor for crude ton-mile demand and tanker rates.","url":"https://www.cnbc.com/2026/06/19/iran-oil-tanker-traffic-strait-hormuz-gulf-vlcc.html"},{"code":"TOP","title":"이란, 해협 재봉쇄 선언…통항 하루 12척으로 급감","src":"Al Jazeera","date":"2026-06-22","kSum":"이스라엘의 레바논 공습에 대응해 이란이 호르무즈 해협을 다시 봉쇄한다고 선언하자 통항이 급감했다. 일요일 통항은 12척으로 전일 35척에서 크게 줄었다.","eSum":"Iran re-declared Hormuz shut over Israel's strikes on Lebanon, and transits collapsed to 12 vessels on Sunday from 35 the previous day.","kImp":"지정학 변동성이 운임·보험·항로를 동시에 흔든다.","eImp":"Geopolitical volatility hits rates, insurance and routing simultaneously.","url":"https://www.aljazeera.com/economy/2026/6/22/shipping-stalls-in-strait-of-hormuz-after-iran-declares-key-waterway-shut"},{"code":"TOP","title":"드루리 WCI 12% 상승…성수기 조기화로 운임 강세","src":"Ship Universe","date":"2026-06","kSum":"드루리 WCI가 6월 18일 40피트당 3,969달러로 12% 올랐다. 상하이-뉴욕은 15% 상승한 6,769달러, 상하이-로스앤젤레스는 10% 오른 5,142달러를 기록했다.","eSum":"Drewry's WCI rose 12% to $3,969/40ft on 18 June; Shanghai-New York up 15% to $6,769 and Shanghai-LA up 10% to $5,142.","kImp":"7월 관세 변경 전 선적 앞당기기와 조기 성수기가 운임을 끌어올린다.","eImp":"Front-loading ahead of July tariffs and an early peak season lift rates.","url":"https://www.shipuniverse.com/news/drewrys-latest-wci-climbs-again-as-early-peak-season-demand-keeps-container-pricing-firm/"},{"code":"TOP","title":"韓 조선 빅3, 1분기 합산 영업익 2.07조원 사상 최대","src":"Financial Today (파이낸셜투데이)","date":"2026-06","kSum":"HD한국조선해양·삼성중공업(Samsung Heavy)·한화오션(Hanwha Ocean) 빅3의 1분기 합산 영업이익이 2조702억원으로 사상 최대를 기록했고, 5월 말 누적 수주는 200억달러를 돌파했다.","eSum":"Korea's Big 3 - HD KSOE, Samsung Heavy, Hanwha Ocean - posted a record combined Q1 operating profit of KRW 2.07tn, with cumulative orders topping USD 20bn by end-May.","kImp":"13년 만의 조선 슈퍼사이클이 실적으로 현실화되고 있다.","eImp":"A 13-year shipbuilding super-cycle is now translating into earnings.","url":"https://www.ftoday.co.kr/news/articleView.html?idxno=359680"},{"code":"TOP","title":"로이즈리스트: 그림자선단 톤수 감소 전망…정상무역 복귀","src":"Lloyd's List","date":"2026-06-19","kSum":"이란산 원유 제재 완화 시 노후 그림자선단이 빠르게 해체 후보로 전락하고, 젊고 규정준수 선박이 호르무즈 화물을 더 실어나를 것으로 분석됐다. 일부 대형 선사는 중동 걸프에서 선박을 빼내고 있다.","eSum":"Lloyd's List sees shadow-fleet tonnage falling as Iran returns to open markets - ageing dark tankers becoming scrap candidates while younger compliant ships lift more cargo; major owners are exiting the Gulf.","kImp":"제재·항행 정상화가 탱커 선대 구조를 재편한다.","eImp":"Sanctions relief and reopened navigation reshape the tanker fleet structure.","url":"https://www.lloydslist.com/LL1157620/The-Week-in-Charts-Shadow-fleet-tanker-tonnage-to-fall--The-dry-bulk-guide-to-El-Nino--Major-shipowners-begin-exiting-vessels-from-MEG"},{"code":"TOP","title":"선원 임금 3년간 6.2% 인상 합의…간부 선원 부족 심화","src":"Maritime Executive","date":"2026-06","kSum":"ITF-JNG 합의로 선원 월 최저임금이 2026~2028년 6.2% 인상된다(AB 기준 673→715달러). 기관장·1등항해사·전자기관사 부족으로 간부 임금은 역사적 기준을 상회한다.","eSum":"An ITF-JNG deal raises the seafarer minimum wage 6.2% over 2026-2028 (AB $673->$715); shortages of Chief Engineers, Chief Officers and ETOs push senior pay above historical benchmarks.","kImp":"인력난이 운영비와 선원 확보 경쟁을 키운다.","eImp":"Crew scarcity drives up opex and competition for officers.","url":"https://www.maritime-executive.com/article/seafarers-win-6-wage-increase-over-three-years-despite-trade-uncertainties"},{"code":"TOP","title":"로이즈리스트: VLCC 운임 사상 최고치…지수 $420K 돌파","src":"Lloyd's List","date":"2026-06","kSum":"호르무즈 위기로 원유탱커 운임이 미증유 영역에 진입해 발틱 VLCC MEG-중국 지수가 하루 $423,736을 기록했다. 운임 시장이 둘로 쪼개졌다.","eSum":"Crude tanker rates entered uncharted territory amid the Hormuz crisis, with the Baltic VLCC MEG-China index hitting $423,736/day and the freight market splitting in two.","kImp":"탱커 운임 폭등이 원유 물류 비용을 급등시킨다.","eImp":"Surging tanker rates spike crude logistics costs.","url":"https://www.lloydslist.com/LL1156492/Crude-tanker-rates-in-unchartered-territory-VLCC-index-tops-420K"},{"code":"TOP","title":"IMO, 첫 글로벌 자율운항선(MASS) 코드 채택","src":"gCaptain","date":"2026-05","kSum":"IMO가 AI·원격운항 상선의 안전 통합을 위한 첫 국제 자율운항선(MASS) 코드를 채택했다. 비강제 코드로 7월 1일 발효하며 경험축적단계를 시작한다.","eSum":"The IMO adopted the first international MASS Code for the safe integration of AI-enabled and remotely operated ships; it takes effect 1 July 2026 as a non-mandatory instrument, starting an experience-building phase.","kImp":"자율운항 규범화가 선대 설계·인력 구조를 바꾼다.","eImp":"Codifying autonomy reshapes fleet design and manning.","url":"https://gcaptain.com/imo-adopts-mass-code-the-autonomous-ship-moves-from-drawing-board-to-regulated-reality/"},{"code":"TOP","title":"후티, 이란전 가세…홍해 상선 위협 재점화","src":"Euronews","date":"2026-06-08","kSum":"예멘 후티가 이란 편에서 참전을 선언하고 이스라엘 연계 선박의 홍해 통항 금지를 발표했다. 호르무즈 봉쇄와 맞물려 해상 위험이 가중됐다.","eSum":"Yemen's Houthis joined the Iran war on Tehran's side and declared a ban on Israel-linked shipping in the Red Sea, compounding maritime risk alongside the Hormuz closure.","kImp":"두 길목 동시 위협이 글로벌 항로를 압박한다.","eImp":"Twin chokepoint threats squeeze global routing.","url":"https://www.euronews.com/2026/06/08/houthis-join-iran-war-fight-threatening-red-sea-shipping-amid-hormuz-closure"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. Accidents","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"싱가포르 파시르판장 앞 보급선 충돌 침몰…3명 사망","src":"SAFETY4SEA","date":"2026-06-12","kSum":"6월 12일 오전 싱가포르 파시르판장 터미널 앞에서 보급선이 상륙정과 충돌 후 침몰했다. 해경이 시신 3구를 수습했으며 사망자는 침몰한 보급선 선원으로 추정된다.","eSum":"A supply boat sank off Pasir Panjang Terminal, Singapore on the morning of 12 June after colliding with a landing craft; the Coast Guard recovered three bodies, believed to be the supply boat's crew.","kCause":"혼잡 수역 충돌(미흡한 견시·교신 추정).","eCause":"Collision in congested waters (likely lookout/communication lapses).","kLes":"혼잡 항만 수역에서 견시 강화와 VHF 사전 교신이 필수다.","eLes":"Enhanced lookout and proactive VHF coordination are vital in busy port waters.","url":"https://safety4sea.com/supply-vessel-sinks-after-collision-in-singapore-three-crew-dead/"},{"code":"ACC","title":"인도 파라디프항 석탄 양하 후 벌크선 화재","src":"Marine Insight","date":"2026","kSum":"인도 파라디프(Paradip)항에서 석탄 양하 작업 후 벌크선에서 화재가 발생했다. 석탄 자기발열 및 잔류 가스가 위험 요인으로 지목된다.","eSum":"A bulk carrier caught fire after coal loading/discharge operations at India's Paradip port, with coal self-heating and residual gases cited as risk factors.","kCause":"석탄화물 자기발열·가스 축적.","eCause":"Coal self-heating and gas accumulation.","kLes":"석탄 화물의 온도·가스 모니터링과 환기 관리가 핵심이다.","eLes":"Temperature/gas monitoring and ventilation control are key for coal cargoes.","url":"https://www.marineinsight.com/shipping-news/bulk-carrier-catches-fire-after-coal-loading-operation-in-indias-paradip-port/"},{"code":"ACC","title":"조디악 자동차운반선 태평양서 화재…선원 대피","src":"Lloyd's List","date":"2026","kSum":"조디악 매리타임(Zodiac Maritime)이 운항하는 자동차운반선에서 태평양 항해 중 화재가 발생해 선원이 대피했다. 차량 화물 화재의 진압 난이도가 다시 부각됐다.","eSum":"Crew were evacuated from a Zodiac Maritime vehicle carrier after a fire broke out in the Pacific, again highlighting the difficulty of fighting vehicle-cargo fires.","kCause":"차량 갑판 화재(전기차/화물 발화원 가능성).","eCause":"Vehicle-deck fire (possible EV/cargo ignition source).","kLes":"PCTC 화재 조기탐지·고정식 소화설비·대피 절차가 중요하다.","eLes":"Early detection, fixed firefighting and evacuation drills matter for PCTC fires.","url":"https://www.lloydslist.com/LL1153746/Crew-evacuated-from-Zodiac-Maritime-vehicle-carrier-in-Pacific-Ocean-after-fire"},{"code":"ACC","title":"인터카고 2026 벌크선 손실 보고서 발간","src":"INTERCARGO","date":"2026","kSum":"인터카고(INTERCARGO)가 2026년 벌크선 손실(Bulk Carrier Casualty) 보고서를 발간했다. 화물액상화·좌초·침수 등 주요 손실 원인과 인명피해 추세를 정리했다.","eSum":"INTERCARGO published its 2026 Bulk Carrier Casualty Report, summarising leading loss causes - cargo liquefaction, grounding, flooding - and fatality trends.","kCause":"복합 원인(액상화·구조·운항).","eCause":"Multiple causes (liquefaction, structural, operational).","kLes":"고체산적화물 수분·IMSBC 준수와 구조 점검이 손실 예방의 핵심이다.","eLes":"Cargo-moisture/IMSBC compliance and structural checks are central to loss prevention.","url":"https://www.intercargo.org/bulk-carrier-casualty-report-2026/"},{"code":"ACC","title":"2026년 6월 와이트섬 인근 영불 해협 선박 사고","src":"Wikipedia","date":"2026-06-16","kSum":"6월 16일 11시40분(UTC)경 와이트섬 남쪽 약 20해리 영해 밖에서 선박 사고가 발생했다. 관계당국이 사고 경위를 조사 중이다.","eSum":"An incident occurred around 11:40 UTC on 16 June about 20 nm south of the Isle of Wight, outside territorial waters; authorities are investigating.","kCause":"조사 진행 중(원인 미확정).","eCause":"Under investigation (cause undetermined).","kLes":"혼잡 해협의 통항분리·견시 준수가 재차 강조된다.","eLes":"TSS adherence and lookout discipline are reinforced in busy straits.","url":"https://en.wikipedia.org/wiki/2026_English_Channel_incident"},{"code":"ACC","title":"북해서 美 국적 탱커·화물선 충돌…양선 화재","src":"CBS News","date":"2026","kSum":"미국 국적 유조선과 화물선이 영국 인근 북해에서 충돌해 양선에 화재가 발생했다. 인명 구조와 오염 대응이 이뤄졌다.","eSum":"A US-flagged tanker and a cargo ship collided in the North Sea off England, setting both vessels on fire; rescue and pollution response were mounted.","kCause":"항행 중 충돌(견시·COLREGs 준수 미흡 추정).","eCause":"Collision under way (likely lookout/COLREGs lapse).","kLes":"혼잡 해역에서 견시·속력·통항분리 준수가 충돌을 막는다.","eLes":"Lookout, safe speed and TSS compliance prevent collisions in busy waters.","url":"https://www.cbsnews.com/news/collision-oil-tanker-cargo-ship-north-sea/"},{"code":"ACC","title":"유조선 세테벨로, 오만만서 기관실 피격…인도 선원 3명 사망","src":"gCaptain","date":"2026-06-09","kSum":"팔라우 선적 유조선 세테벨로(Settebello)가 6월 9일 오만만에서 기관실을 피격당해 화재가 발생했고 인도 선원 3명이 사망, 21명이 구조됐다. 선박관리사는 국제조사를 요구했다.","eSum":"The Palau-flagged tanker Settebello was struck on its engine room in the Gulf of Oman on 9 June, causing a fire; three Indian seafarers died and 21 were rescued, with the manager demanding an international probe.","kCause":"군사적 무력화(봉쇄 집행)에 따른 화재.","eCause":"Fire from a military disabling (blockade enforcement).","kLes":"전쟁위험구역 회피·해상경보 준수가 선원 안전의 핵심이다.","eLes":"Avoiding war-risk zones and heeding advisories is central to crew safety.","url":"https://gcaptain.com/ship-manager-demands-international-probe-into-fatal-u-s-attack-on-tanker/"},{"code":"ACC","title":"화물선, 기관실 화재로 포츠머스 예인","src":"Marine Insight","date":"2026","kSum":"한 화물선이 기관실 화재 후 영국 포츠머스(Portsmouth)항으로 예인됐다. 화재 진압 후 안전 점검이 진행됐다.","eSum":"A cargo ship was towed to Portsmouth, UK after an engine-room fire, with safety checks following the blaze.","kCause":"기관실 화재(연료누설·고온표면 발화 가능).","eCause":"Engine-room fire (possible fuel leak/hot-surface ignition).","kLes":"연료라인 점검·고온표면 차폐·고정식 소화설비가 ER 화재를 줄인다.","eLes":"Fuel-line checks, hot-surface shielding and fixed firefighting reduce ER fires.","url":"https://www.marineinsight.com/shipping-news/cargo-ship-towed-to-portsmouth-port-after-engine-room-fire/"},{"code":"ACC","title":"컨테이너선 기관실 화재, 윌밍턴서 4명 부상","src":"gCaptain","date":"2026","kSum":"미국 윌밍턴(Wilmington)항에서 컨테이너선 기관실 화재로 4명이 부상했다. 신속한 대응으로 화재가 통제됐다.","eSum":"An engine-room fire on a containership injured four at the Port of Wilmington, USA; rapid response brought the blaze under control.","kCause":"정박 중 기관실 화재(작업·점화원 관리 미흡 가능).","eCause":"At-berth ER fire (possible hot-work/ignition-source control gap).","kLes":"정박·작업 중 화기관리와 비상대응 훈련이 부상을 줄인다.","eLes":"Hot-work control and emergency drills at berth reduce injuries.","url":"https://gcaptain.com/engine-room-fire-on-containership-injures-four-at-port-of-wilmington/"},{"code":"ACC","title":"탱커 메드아틀란틱, 싱가포르 수역서 기관실 화재","src":"gCaptain","date":"2026","kSum":"탱커 메드아틀란틱(MED ATLANTIC)이 싱가포르 수역에서 기관실 화재를 겪었다. 인근 해역 교통량을 고려한 신속 대응이 이뤄졌다.","eSum":"The tanker MED ATLANTIC suffered an engine-room fire in Singapore waters, prompting rapid response given heavy local traffic.","kCause":"기관실 화재(고온표면·연료누설 가능).","eCause":"Engine-room fire (hot surface/fuel-leak possible).","kLes":"혼잡 수역 화재 시 예인·소화·교통통제 협조가 중요하다.","eLes":"In busy waters, towage, firefighting and traffic-control coordination are vital.","url":"https://gcaptain.com/engine-room-fire-on-tanker-med-atlantic-in-singapore-waters/"}]},{"code":"PSC","type":"news","kTitle":"Section 3. Port State Control","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"DNV: 1분기 억류 64건…ISM·정비 결함이 주도","src":"DNV","date":"2026","kSum":"DNV 선대의 2026년 1분기 억류는 64건으로 전년 동기 52건보다 증가했다. 컨테이너·벌크·일반화물선이 83%를 차지했고 84%가 파리·도쿄 MOU에서 발생했다. ISM(15150)·정비(15109) 결함이 주요 억류 사유였다.","eSum":"DNV recorded 64 detentions in Q1 2026 (up from 52 a year earlier); container, bulk and general cargo made up 83%, with 84% in the Paris/Tokyo MoUs. ISM (15150) and maintenance (15109) deficiencies dominated.","kImp":"ISM 이행과 선체·장비 정비가 억류 회피의 핵심이다.","eImp":"ISM implementation and ship/equipment maintenance are key to avoiding detention.","url":"https://www.dnv.com/news/2026/port-state-control-q1-2026-detention-review-and-other-updates/"},{"code":"PSC","title":"파리 MOU 위원회, 신흥 해상 리스크 집중 대응","src":"SAFETY4SEA","date":"2026","kSum":"파리 MOU 위원회가 신흥 해상 안전 리스크를 점검하고 2026년 합동 집중점검(CIC)을 확정했다. 결함·억류 데이터 공유와 표적선박 선정 정교화를 추진한다.","eSum":"The Paris MoU Committee reviewed emerging maritime risks and confirmed the 2026 joint CIC, advancing deficiency/detention data sharing and refined ship targeting.","kImp":"표적선정 강화로 노후·저성과 선박의 점검 압박이 커진다.","eImp":"Sharper targeting increases inspection pressure on older/low-performing ships.","url":"https://safety4sea.com/paris-mou-committee-targets-emerging-maritime-risks/"},{"code":"PSC","title":"도쿄·파리 MOU, 선원임금·고용계약 합동 CIC 예고","src":"NorthStandard","date":"2026","kSum":"도쿄·파리 MOU가 선원 임금과 선원고용계약(SEA)에 대한 합동 집중점검(CIC)을 시행한다. 표준 질문지로 임금 지급·계약 적정성·근로조건 준수를 검증한다.","eSum":"Tokyo and Paris MoUs will run a joint CIC on crew wages and Seafarer Employment Agreements, using a standard questionnaire to verify wage payment, contract validity and working conditions.","kImp":"임금·계약 서류 정비와 기록 관리가 점검 통과의 관건이다.","eImp":"Wage/contract documentation and recordkeeping are critical to passing.","url":"https://north-standard.com/insights-and-resources/resources/news/tokyo-and-paris-mous-on-port-state-control"},{"code":"PSC","title":"도쿄·파리 MOU, 평형수관리협약 CIC 시행","src":"Tokyo MOU Kaikoumu","date":"2026","kSum":"도쿄·파리 MOU가 평형수관리협약(BWM Convention) 집중점검(CIC)을 시행한다. 평형수관리계획·기록부·처리설비 작동 등을 중점 검증한다.","eSum":"Tokyo and Paris MoUs are conducting a CIC on the Ballast Water Management Convention, focusing on the BWM plan, record book and treatment-system operation.","kImp":"BWMS 작동상태·기록부 정합성 점검이 필수다.","eImp":"Verifying BWMS operation and record-book consistency is essential.","url":"https://kaikoumu.zendesk.com/hc/en-us/articles/49521581526681--PSC-Concentrated-Inspection-Campaign-CIC-on-the-Ballast-Water-Management-Convention-to-be-conducted-under-the-Tokyo-MOU-and-Paris-MOU"},{"code":"PSC","title":"RiSK4SEA PSI 6월: 전 선종 '심각위험' 진입","src":"SAFETY4SEA","date":"2026-06","kSum":"RiSK4SEA PSC 스트레스지수(PSI) 6월 전망에서 벌크·탱커·컨테이너·일반화물 전 선종이 PSI-9 '심각위험'에 진입했다. 벌커는 2,371회 점검 중 118건 억류로 기준比 69% 급증했다.","eSum":"RiSK4SEA's June PSI outlook shows bulkers, tankers, containers and general cargo all entering the PSI-9 'critical risk' zone; bulkers logged 118 detentions from 2,371 inspections, up ~69% vs baseline.","kImp":"단속 강화로 전 선종의 점검·억류 리스크가 커졌다.","eImp":"Heightened enforcement raises inspection/detention risk across all types.","url":"https://safety4sea.com/cm-risk4sea-psi-outlook-of-june-2026-signals-broad-deterioration-in-global-psc-enforcement-climate/"},{"code":"PSC","title":"RISK4SEA, 글로벌 PSC 인텔리전스 레이어 출시","src":"RISK4SEA / WN","date":"2026-05-28","kSum":"RISK4SEA가 실시간 항만 인텔리전스와 PSC 핫스팟 모니터링을 위한 글로벌 PSC 인텔리전스 레이어를 출시했다. 항만별 점검 리스크를 사전 가시화한다.","eSum":"RISK4SEA launched a Global PSC Intelligence Layer for live port intelligence and PSC hotspot monitoring, giving advance visibility into port-level inspection risk.","kImp":"데이터 기반 기항 계획이 억류 리스크를 낮춘다.","eImp":"Data-driven port-call planning lowers detention risk.","url":"https://article.wn.com/view-steel/2026/05/28/RISK4SEA_launches_Global_PSC_Intelligence_Layer_for_live_por/"},{"code":"PSC","title":"마셜아일랜드 선적, PSC 억류 추세 점검","src":"IRI Marshall Islands","date":"2026","kSum":"마셜아일랜드 선적(IRI)이 PSC 억류 추세를 분석했다. 1분기 파리·도쿄·USCG 체제에서 601건의 억류가 기록됐다.","eSum":"The Marshall Islands Registry (IRI) reviewed PSC detention trends, noting 601 detentions across the Paris/Tokyo/USCG regimes in Q1.","kImp":"선적 차원의 추세 분석이 사전 대비에 도움 된다.","eImp":"Flag-level trend analysis aids proactive preparation.","url":"https://www.register-iri.com/blog/psc/"},{"code":"PSC","title":"IRClass, 벨리즈 선적에 RISK4SEA PSC 플랫폼 적용","src":"IRClass","date":"2026","kSum":"IRClass가 벨리즈(Belize) 선적에 RISK4SEA PSC 인텔리전스 플랫폼을 적용하는 기술회람을 발행했다. 선적국 차원의 PSC 데이터 활용이 확산된다.","eSum":"IRClass issued a technical circular implementing the RISK4SEA PSC intelligence platform for the Belize flag, spreading flag-level use of PSC data.","kImp":"선적국의 데이터 도입이 점검 대비를 표준화한다.","eImp":"Flag adoption of data standardises inspection readiness.","url":"https://www.irclass.org/technical-circulars/belize-implementation-of-risk4sea-psc-intelligence-platform/"},{"code":"PSC","title":"AMSA, 호주항 선박 억류 데이터베이스 운영","src":"AMSA","date":"2026","kSum":"호주해사안전청(AMSA)이 2022년 이후 호주항 선박 억류 정보를 데이터베이스로 공개·갱신하고 있다. 도쿄 MOU와 연계해 억류 이력을 공유한다.","eSum":"AMSA maintains and updates a database of ship detentions in Australian ports from 2022 onwards, sharing detention histories in coordination with the Tokyo MoU.","kImp":"억류 이력 공개가 표적선박 선정에 반영된다.","eImp":"Public detention histories feed into ship targeting.","url":"https://www.amsa.gov.au/vessels-operators/port-state-control/recent-ship-detentions-2022-onwards"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. Car Carriers (PCTC)","eTitle":"Section 4. Car Carriers (PCTC)","items":[{"code":"PCTC","title":"살라움라인, 중국에 LNG·암모니아레디 PCTC 2척 발주","src":"ship.energy","date":"2026","kSum":"살라움라인(Sallaum Lines)이 중국 샤먼조선(Xiamen Shipbuilding)에 8,600 CEU·5단 가변갑판 LNG 이중연료 PCTC 2척을 발주하고 추가 2척 옵션을 확보했다. 인도 시 LNG·VLSFO·LSMGO 운항이 가능하며 암모니아레디 표기를 갖춘다.","eSum":"Sallaum Lines ordered two 8,600-CEU, five-liftable-deck LNG dual-fuel PCTCs at Xiamen Shipbuilding with options for two more; ammonia-ready on delivery, running on LNG/VLSFO/LSMGO.","kImp":"친환경 선대 확충으로 IMO 2030·EU 규제에 대비한다.","eImp":"Greener fleet additions hedge IMO 2030 and EU rules.","url":"https://ship.energy/energy/sallaum-lines-orders-dual-fuel-lng-ammonia-ready-pctcs-in-china/"},{"code":"PCTC","title":"레이 카캐리어스, HD현대에 2.7억달러 PCTC 발주 연계","src":"Riviera","date":"2026","kSum":"레이 카캐리어스(Ray Car Carriers)가 HD현대(HD Hyundai)와 약 2억7천만달러 규모 PCTC 신조 계약에 연계된 것으로 보도됐다. 자동차운반선 선대 확장 수요가 이어진다.","eSum":"Ray Car Carriers has been linked to a ~US$270M PCTC newbuilding contract at HD Hyundai, reflecting continued fleet-expansion demand in car carriers.","kImp":"고선가에도 PCTC 신조 발주가 지속된다.","eImp":"PCTC newbuilding orders persist despite high prices.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/ray-car-carriers-linked-to-us270m-pctc-newbuilding-contract-at-hd-hyundai-88493"},{"code":"PCTC","title":"NOCC, 암모니아레디 PCTC 3번선 추가 발주","src":"The Loadstar","date":"2026","kSum":"NOCC가 암모니아레디 PCTC 신조 3번선을 발주목록에 추가했다. 무탄소 연료 전환을 염두에 둔 단계적 선대 현대화 전략이다.","eSum":"NOCC added a third ammonia-ready PCTC newbuild to its orderbook, part of a phased fleet-modernisation strategy geared to zero-carbon fuels.","kImp":"암모니아레디 발주가 PCTC 표준으로 자리잡는다.","eImp":"Ammonia-ready specs are becoming the PCTC norm.","url":"https://theloadstar.com/nocc-adds-third-ammonia-ready-pctc-newbuild-orderbook/"},{"code":"PCTC","title":"UECC, 친환경 PCTC 신조 2척 발주","src":"LNG Industry","date":"2026-03-04","kSum":"UECC가 친환경 사양의 PCTC 신조 2척을 발주했다. 단거리 유럽 항로의 배출 규제 대응을 위한 저탄소 추진 사양을 채택했다.","eSum":"UECC ordered a pair of eco-friendly PCTC newbuilds, adopting low-carbon propulsion to meet emissions rules on its short-sea European trades.","kImp":"역내 배출규제가 친환경 자동차선 발주를 견인한다.","eImp":"Regional emissions rules drive eco car-carrier ordering.","url":"https://www.lngindustry.com/small-scale-lng/04032026/uecc-orders-eco-friendly-pctc-newbuild-pair/"},{"code":"PCTC","title":"살라움라인, LNG 이중연료 자동차운반선 신조 인도","src":"MarineLink","date":"2026","kSum":"살라움라인이 LNG 이중연료 자동차운반선 신조 2척을 인도받았다. 신조 인도로 선대 평균 선령을 낮추고 연료 효율을 개선한다.","eSum":"Sallaum Lines took delivery of a pair of LNG dual-fuel car carrier newbuilds, lowering fleet age and improving fuel efficiency.","kImp":"신조 인도로 운영 효율과 규제 적합성이 향상된다.","eImp":"Newbuild deliveries improve efficiency and regulatory fit.","url":"https://www.marinelink.com/news/sallaum-takes-delivery-lng-dualfueled-car-540038"},{"code":"PCTC","title":"자동차선 용선시장, 수출 둔화에 운임 하락 전환","src":"Index1520","date":"2026","kSum":"완성차 수출 둔화로 자동차운반선 용선시장 운임이 하락세로 전환됐다. 클락슨은 2025·2026년 선대 12%·8% 증가에 수요 1~2% 증가로 공급과잉을 전망한다.","eSum":"Car-carrier charter rates have turned down as vehicle exports level off; Clarksons sees fleet growth of 12%/8% in 2025/26 against just 1-2% demand growth, pointing to oversupply.","kImp":"선대 증가가 PCTC 운임 하방 압력을 키운다.","eImp":"Fleet growth adds downward pressure on PCTC rates.","url":"https://index1520.com/en/news/izmenenie-okeanskikh-stavok-na-rynke-charternykh-perevozok-avtomobiley-na-fone-snizheniya-eksporta/"},{"code":"PCTC","title":"현대글로비스, 18.4억달러 세계 최대 PCTC 발주","src":"The Loadstar","date":"2026","kSum":"현대글로비스(Hyundai Glovis)가 약 18억4천만달러를 투입해 세계 최대급 PCTC 신조를 발주한다. 자동차 물류 수직계열화와 선대 확장을 가속한다.","eSum":"Hyundai Glovis will spend ~US$1.84bn to build the world's largest PCTCs, accelerating vertical integration of vehicle logistics and fleet expansion.","kImp":"대형 신조가 단위운송비와 경쟁력을 좌우한다.","eImp":"Mega-newbuilds drive unit costs and competitiveness.","url":"https://theloadstar.com/hyundai-glovis-to-spend-1-84bn-to-build-worlds-largest-pctcs/"},{"code":"PCTC","title":"대형 암모니아레디 PCTC 인도로 RoRo 용량 긴축","src":"Breakbulk News","date":"2026","kSum":"대형 암모니아레디 PCTC가 잇따라 인도되며 RoRo 용량이 긴축되는 한편, 프로젝트 화물 운임은 2026년 반등을 앞두고 잠시 정체됐다.","eSum":"Giant ammonia-ready PCTCs are arriving and tightening RoRo capacity, while project-cargo rates pause before an expected 2026 rebound.","kImp":"친환경 대형선 인도가 시장 수급을 재편한다.","eImp":"Green mega-deliveries reshape capacity balance.","url":"https://breakbulk.news/roro-capacity-tightens-as-giant-ammonia-ready-pctcs-arrive-while-project-cargo-rates-pause-before-a-2026-rebound/"},{"code":"PCTC","title":"PCTC 신조, 완성차 해상물류 수요에 맞춰 증가","src":"Automotive Logistics","date":"2026","kSum":"선사들이 완성차 해상물류 수요에 맞춰 PCTC 용량을 확대하고 있다. 수급이 점차 균형을 찾으며 2025~26년 일시적 공급과잉 가능성도 제기된다.","eSum":"Vessel operators are bringing in more PCTC capacity to match finished-vehicle shipping demand, with supply rebalancing and possible oversupply in 2025-26.","kImp":"용량 확대가 운임·서비스 경쟁을 심화한다.","eImp":"Capacity additions intensify rate and service competition.","url":"https://www.automotivelogistics.media/vehicle-logistics/vessel-operators-are-bringing-in-more-capacity-for-maritime-finished-vehicle-shipments/212292"}]},{"code":"WW","type":"news","kTitle":"Section 5. Wallenius Wilhelmsen","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"WW, 자동차운송 계약에 4.2억달러 추가 연장","src":"Splash247","date":"2026-06","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 유럽 주요 완성차 업체와의 운송계약을 약 4억2천만달러 규모로 연장했다. 3년 연장(2028년 중반~2031년 중반)에 저배출 연료 사용이 포함된다.","eSum":"Wallenius Wilhelmsen extended a contract with a major European carmaker worth ~US$420M, a three-year extension (mid-2028 to mid-2031) including low-emission fuel use.","kImp":"장기계약 연장으로 운임·물량 가시성이 높아진다.","eImp":"Long-term renewal improves rate and volume visibility.","url":"https://splash247.com/wallenius-wilhelmsen-adds-420m-to-car-shipping-contract/"},{"code":"WW","title":"WW, 운송서비스 연장으로 5억달러 추가 확보","src":"MarineLink","date":"2026-06","kSum":"발레니우스 빌헬름센이 운송 서비스 연장 계약으로 약 5억달러를 추가 확보했다. 고정 계약 비중 확대로 수익 안정성을 강화하고 있다.","eSum":"Wallenius Wilhelmsen secured about US$500M from shipping-service extensions, strengthening earnings stability via a larger contracted base.","kImp":"계약 기반 확대가 시황 변동 완충 역할을 한다.","eImp":"A larger contract base cushions market volatility.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-bags-m-shipping-533232"},{"code":"WW","title":"WW, 2026년 전망 하향…벙커비 상승 반영","src":"Ship & Bunker","date":"2026-06","kSum":"발레니우스 빌헬름센이 벙커유 가격 상승을 반영해 2026년 실적 전망을 하향했다. 연료비 부담이 마진에 압력을 가하고 있다.","eSum":"Wallenius Wilhelmsen lowered its 2026 outlook to reflect rising bunker costs, with fuel expense pressuring margins.","kImp":"연료비가 자동차선 수익성의 핵심 변수다.","eImp":"Fuel cost is a key driver of car-carrier profitability.","url":"https://shipandbunker.com/news/emea/163558-wallenius-wilhelmsen-lowers-2026-outlook-as-bunker-costs-rise"},{"code":"WW","title":"WW, 2026 회계연도 가이던스 공시","src":"Wallenius Wilhelmsen","date":"2026","kSum":"발레니우스 빌헬름센이 2026 회계연도 전망과 2025년 갱신 가이던스를 거래소에 공시했다. 시황·연료·계약 갱신 전제를 반영한 실적 가이드를 제시했다.","eSum":"Wallenius Wilhelmsen issued a stock-exchange notice on its 2026 financial-year outlook and updated 2025 guidance, reflecting market, fuel and contract-renewal assumptions.","kImp":"공식 가이던스가 투자자 기대를 재설정한다.","eImp":"Official guidance resets investor expectations.","url":"https://www.walleniuswilhelmsen.com/stock-exchange-notice/wallenius-wilhelmsen-2026-financial-year-outlook-and-updated-2025-guidance"},{"code":"WW","title":"WW 1분기 조정 EBITDA 3.89억달러…순익 1.77억달러","src":"Wallenius Wilhelmsen","date":"2026-05","kSum":"발레니우스 빌헬름센의 1분기 조정 EBITDA는 3억8,900만달러로 전분기比 3% 감소했고 순이익은 1억7,700만달러로 안정적이었다. 매출은 12억5,300만달러였다.","eSum":"Wallenius Wilhelmsen's Q1 adjusted EBITDA was US$389M (-3% QoQ) with net profit stable at US$177M on revenue of US$1,253M.","kImp":"물류 호조가 해운 약세를 일부 상쇄했다.","eImp":"Strong logistics partly offset softer shipping.","url":"https://www.walleniuswilhelmsen.com/storage/images/Investor-relations/Wallenius-Wilhelmsen-Quarterly-report-Q1-2026.pdf"},{"code":"WW","title":"WW, 1년 단위 운송계약 신규 체결","src":"TradingView (Reuters)","date":"2026","kSum":"발레니우스 빌헬름센이 2026년부터 시작되는 1년 단위 신규 운송계약을 체결했다고 공시했다. 단기 계약으로 시황 변동에 유연하게 대응한다.","eSum":"Wallenius Wilhelmsen entered a new one-year shipping contract starting 2026, adding flexibility to respond to market swings.","kImp":"단·장기 계약 믹스로 리스크를 분산한다.","eImp":"A mix of short- and long-term deals diversifies risk.","url":"https://www.tradingview.com/news/reuters.com,2026:newsml_FWN3Y716T:0-wallenius-wilhelmsen-enters-one-year-shipping-contract-starting-2026/"},{"code":"WW","title":"WW, EUKOR 옵션 계약 수정…단기 부채 축소","src":"TipRanks","date":"2026-04","kSum":"발레니우스 빌헬름센과 HMG가 EUKOR 지분 풋·콜 옵션을 OCC(최소 50% 물량 약정) 유지 동안 행사하지 않기로 합의했다. 최초 행사 가능일은 2031년 1월 1일로, EUKOR 풋 부채는 8억5,100만달러로 감소했다.","eSum":"WW and HMG agreed the EUKOR put/call options cannot be exercised while the OCC commits >=50% of HMG volumes (earliest exercise 1 Jan 2031); EUKOR put liability fell to US$851M.","kImp":"지배구조·부채 불확실성이 완화됐다.","eImp":"Governance and liability uncertainty is reduced.","url":"https://www.tipranks.com/news/company-announcements/wallenius-wilhelmsen-revises-eukor-option-deal-cutting-near-term-liability"},{"code":"WW","title":"WW, 에퀴노르와 2년 바이오메탄올 공급 계약","src":"Equinor","date":"2026-03-11","kSum":"발레니우스 빌헬름센이 에퀴노르(Equinor)와 노르웨이산 매스밸런스 바이오메탄올을 안트베르펜·제브뤼헤에서 공급받는 2년 계약을 체결했다. ISCC EU 인증으로 CO2 95% 저감이 기대된다.","eSum":"Wallenius Wilhelmsen signed a two-year deal with Equinor for Norwegian mass-balanced bio-methanol delivered at Antwerp and Zeebrugge; ISCC-EU certified, ~95% CO2 cut.","kImp":"메탄올 신조의 연료 공급망을 선제 확보한다.","eImp":"Secures the fuel supply chain for methanol newbuilds.","url":"https://www.equinor.com/news/20260311-bio-methanol-agreement-wallenius-wilhelmsen"},{"code":"WW","title":"WW, 안트베르펜·제브뤼헤 바이오메탄올 벙커 확보","src":"SAFETY4SEA","date":"2026","kSum":"발레니우스 빌헬름센이 다가오는 이중연료 메탄올선을 위해 안트베르펜·제브뤼헤에서 바이오메탄올 벙커링을 2026년 말부터 받기로 했다. 항만 단위 친환경 연료 공급 체계를 구축한다.","eSum":"Wallenius Wilhelmsen will bunker bio-methanol at Antwerp and Zeebrugge from late 2026 for its upcoming dual-fuel methanol vessels, building port-level green-fuel supply.","kImp":"항만 벙커링 확보가 메탄올 운항의 전제다.","eImp":"Securing port bunkering underpins methanol operations.","url":"https://safety4sea.com/wallenius-wilhelmsen-signs-agreement-for-bio-methanol-in-antwerp-and-zeebrugge/"},{"code":"WW","title":"WW, 에퀴노르 2년 바이오메탄올 공급 상세 공개","src":"Manifold Times","date":"2026","kSum":"발레니우스 빌헬름센이 에퀴노르로부터 2년간 바이오메탄올 벙커유를 공급받는 계약의 세부 사항을 공개했다. 노르웨이 생산·유럽 인도 구조로 인증 연료를 안정 조달한다.","eSum":"Wallenius Wilhelmsen detailed its two-year Equinor bio-methanol bunker supply - produced in Norway, delivered in Europe - to secure certified fuel.","kImp":"장기 연료계약이 가격·공급 리스크를 줄인다.","eImp":"Long-term fuel contracts cut price and supply risk.","url":"https://www.manifoldtimes.com/news/wallenius-wilhelmsen-secures-two-year-bio-methanol-bunker-fuel-supply-from-equinor/"},{"code":"WW","title":"WW, 브레이크벌크 강화…벤트 부사장 승진","src":"Heavy Lift PFI","date":"2026-06-04","kSum":"발레니우스 빌헬름센이 산업 글로벌 영업조직을 신설하고 카르스텐 벤트(Carsten Wendt)를 EMEA 산업영업 부사장으로 승진시켰다. 미국 AI·전력망 수요로 변압기 등 고중량 화물 수요가 견조하다.","eSum":"Wallenius Wilhelmsen created an industrial global sales unit and promoted Carsten Wendt to VP industrial sales EMEA; H&H/breakbulk demand is solid, driven by US AI/grid transformers.","kImp":"고중량·브레이크벌크가 새로운 성장축으로 부상한다.","eImp":"High & heavy/breakbulk emerges as a new growth pillar.","url":"https://www.heavyliftpfi.com/news/2026/06/04/wendt-promoted-as-wallenius-wilhelmsen-strengthens-breakbulk-focus/"},{"code":"WW","title":"WW, 역대 최중량 단일 브레이크벌크 화물 운송","src":"Heavy Lift PFI","date":"2026","kSum":"발레니우스 빌헬름센이 역대 최중량 단일 브레이크벌크 화물 운송을 수행했다. RoRo 기반 고중량 운송 역량을 입증했다.","eSum":"Wallenius Wilhelmsen delivered its heaviest-ever single breakbulk piece, demonstrating its RoRo-based heavy-cargo capability.","kImp":"고중량 운송 역량이 프로젝트 화물 경쟁력을 높인다.","eImp":"Heavy-lift capability boosts project-cargo competitiveness.","url":"https://www.heavyliftpfi.com/projects/wallenius-wilhelmsen-delivers-its-heaviest-single-breakbulk-piece-ever/35147.article"},{"code":"WW","title":"코그니전트, WW 레거시 시스템·AI 현대화 추진","src":"StockTitan","date":"2026-02","kSum":"코그니전트(Cognizant)가 발레니우스 빌헬름센과 파트너십을 확대해 레거시 포트폴리오 현대화와 실용 AI 효율화를 지원한다. 통합 공급망 파트너로의 전환을 뒷받침한다.","eSum":"Cognizant expanded its partnership with Wallenius Wilhelmsen to modernise legacy portfolios and introduce practical AI efficiencies, supporting its shift to an integrated supply-chain partner.","kImp":"디지털 전환이 운영비 절감과 서비스 차별화를 견인한다.","eImp":"Digital transformation drives cost savings and service differentiation.","url":"https://www.stocktitan.net/news/CTSH/cognizant-to-provide-strategic-technology-services-for-wallenius-q47p4or67a5i.html"},{"code":"WW","title":"WW 실적·전망 트래커 업데이트","src":"Quartr","date":"2026","kSum":"발레니우스 빌헬름센(WAWI)의 실적·전망 요약이 업데이트됐다. 분기 실적, 가이던스, 투자자 일정 등 핵심 지표를 추적한다.","eSum":"An updated investor summary for Wallenius Wilhelmsen (WAWI) tracks quarterly results, guidance and investor-calendar items.","kImp":"투자자 지표 추적이 시장 기대 형성에 활용된다.","eImp":"Tracking investor metrics informs market expectations.","url":"https://quartr.com/companies/wallenius-wilhelmsen_4483"}]},{"code":"EE","type":"news","kTitle":"Section 6. Energy Efficiency","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE","title":"메탄올·암모니아, 무탄소 연료로 빠른 진전","src":"Global Maritime Forum","date":"2026","kSum":"글로벌 마리타임 포럼은 메탄올선 약 60척 운항·300척 이상 발주·20개 항만 그린메탄올 벙커링으로 초기 스케일에 진입했다고 평가했다. 암모니아는 개념검증 단계에 근접했다.","eSum":"The Global Maritime Forum says methanol has reached early scale - ~60 vessels operating, 300+ on order, ~20 ports bunkering green methanol - while ammonia nears proof of concept.","kImp":"연료 공급망 확충이 스케일업의 관건이다.","eImp":"Scaling the fuel supply chain is the key bottleneck.","url":"https://globalmaritimeforum.org/press/methanol-and-ammonia-progressing-rapidly-extra-push-needed-to-scale/"},{"code":"EE","title":"2026 그린연료 경쟁: LNG·메탄올·암모니아·원자력","src":"Ship Universe","date":"2026","kSum":"2026년 그린연료 경쟁이 LNG·메탄올·암모니아와 원자력 옵션으로 확산되고 있다. 암모니아 엔진 시험은 탱크-투-웨이크 배출 최대 95% 저감 가능성을 시사한다.","eSum":"The 2026 green-fuel race spans LNG, methanol, ammonia and the nuclear option; ammonia engine tests suggest tank-to-wake cuts of up to 95%.","kImp":"연료 선택이 신조·개조 투자 의사결정을 좌우한다.","eImp":"Fuel choice shapes newbuild and retrofit investment decisions.","url":"https://www.shipuniverse.com/the-great-green-fuel-race-in-2026-lng-methanol-ammonia-and-the-nuclear-option/"},{"code":"EE","title":"FuelEU Maritime, 6월 30일 적합증서·벌금 마감","src":"Lloyd's Register","date":"2026-06","kSum":"FuelEU Maritime 규정에 따라 선박은 2026년 6월 30일까지 적합서류(DoC)를 비치하고 벌금 납부를 완료해야 한다. 온실가스 집약도 목표 미달 시 페널티가 부과된다.","eSum":"Under FuelEU Maritime, ships must hold the Document of Compliance on board and complete penalty payments by 30 June 2026, with penalties for missing GHG-intensity targets.","kImp":"적합성 관리 미흡 시 즉각적 비용 부담이 발생한다.","eImp":"Poor compliance management triggers immediate cost exposure.","url":"https://www.lr.org/en/services/statutory-compliance/fueleu-regulation/"},{"code":"EE","title":"풍력보조추진, FuelEU서 최대 5% GHG 저감 인정","src":"bound4blue","date":"2026","kSum":"풍력보조추진이 선박 추진 에너지의 15% 이상을 담당하면 FuelEU Maritime 온실가스 집약도 계산에서 최대 5% 저감을 인정받는다. 윈드 솔루션의 규제 인센티브가 명확해지고 있다.","eSum":"Wind-assisted propulsion earns up to a 5% GHG-intensity reduction under FuelEU Maritime when it provides >=15% of propulsion energy, clarifying the regulatory incentive for wind solutions.","kImp":"풍력 보조가 규제 적합성과 연료비를 동시에 개선한다.","eImp":"Wind assistance improves both compliance and fuel costs.","url":"https://bound4blue.com/fueleu-maritime-compliance-with-wind/"},{"code":"EE","title":"EU ETS 해운 편입, FuelEU와 동반 적용","src":"ABS Eagle","date":"2026","kSum":"EU 배출권거래제(EU ETS)가 2024년부터 해운에 확대 적용되며 FuelEU Maritime와 함께 종합적 탈탄소 프레임워크를 형성한다. 탄소가격과 연료수요 압력이 병행된다.","eSum":"The EU ETS has extended to shipping since 2024 and works in tandem with FuelEU Maritime, forming a comprehensive decarbonisation framework combining carbon pricing and fuel-demand pressure.","kImp":"탄소비용 내재화가 항로·연료 전략을 바꾼다.","eImp":"Internalised carbon costs reshape route and fuel strategy.","url":"https://ww2.eagle.org/en/rules-and-resources/regulatory-updates/eu-ets-inclusion-of-maritime-emissions.html"},{"code":"EE","title":"RMI, 2030년 항만 그린메탄올·암모니아 공급 청사진","src":"RMI","date":"2026","kSum":"RMI는 항만이 2030년까지 그린메탄올·암모니아를 공급하기 위한 청사진 보고서를 발표했다. 항만 인프라·공급망·수요 신호의 단계적 정렬을 제안한다.","eSum":"RMI released a blueprint for how ports can supply green methanol and ammonia by 2030, proposing phased alignment of port infrastructure, supply chains and demand signals.","kImp":"항만 준비가 무탄소 연료 확산의 선결 조건이다.","eImp":"Port readiness is a precondition for zero-carbon fuel uptake.","url":"https://rmi.org/press-release/new-report-provides-a-blueprint-for-how-ports-can-supply-green-methanol-and-ammonia-by-2030/"},{"code":"EE","title":"DNV, FuelEU Maritime 적합 인사이트 제공","src":"DNV","date":"2026","kSum":"DNV가 FuelEU Maritime 적합 전략 인사이트를 제공한다. 풀링·바이오연료·풍력 보조 등 적합성 잔액 관리 방안을 정리했다.","eSum":"DNV provides FuelEU Maritime compliance insights, outlining options to manage the compliance balance - pooling, biofuels and wind assistance.","kImp":"적합성 잔액의 전략적 관리가 비용을 좌우한다.","eImp":"Strategic compliance-balance management drives cost outcomes.","url":"https://www.dnv.com/maritime/insights/topics/fueleu-maritime/"},{"code":"EE","title":"풍력보조추진 FuelEU 계산법, 정밀 검토 필요","src":"BetterSea","date":"2026","kSum":"풍력보조추진의 FuelEU 적합성 기여는 에너지 사용량 산정 방식에 따라 달라져, 계산법에 대한 정밀 검토가 필요하다는 분석이 제시됐다. 저연료 선박일수록 기준 에너지가 작아 효과가 달라진다.","eSum":"Analysis warns that wind-assisted propulsion's FuelEU benefit depends on how energy use is calculated and deserves a closer look, since lower-consumption ships have a smaller energy base.","kImp":"계산 방식 이해가 풍력 투자 ROI 평가에 필수다.","eImp":"Understanding the calculation is essential to assess wind-investment ROI.","url":"https://www.bettersea.tech/post/wind-assisted-propulsion-under-fueleu-maritime-why-the-calculation-deserves-a-closer-look"},{"code":"EE","title":"로테르담항, 육상전력·대체연료 벙커링 투자","src":"Riviera","date":"2026","kSum":"로테르담항이 육상전력과 대체연료 벙커링 인프라에 투자한다. 심해 컨테이너터미널 3곳에 35개 접속점의 육상전력 설비를 구축한다.","eSum":"The Port of Rotterdam is investing in shore power and alternative-fuel bunkering, installing shore-power facilities with 35 connection points across three deep-sea container terminals.","kImp":"항만 인프라가 배출규제 대응의 토대가 된다.","eImp":"Port infrastructure underpins emissions-rule compliance.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/rotterdam-port-invests-in-shore-power-alternative-fuels-bunkering-88511"},{"code":"EE","title":"NYK 계열, 벨기에 첫 RoRo 육상전력 시설 가동","src":"Ship & Bunker","date":"2026","kSum":"NYK 계열사가 벨기에 첫 RoRo 전용 육상전력 시설을 가동했다. 정박 중 배출·소음을 줄이는 친환경 항만 운영을 확대한다.","eSum":"An NYK unit launched Belgium's first RoRo shore-power facility, cutting at-berth emissions and noise as part of greener port operations.","kImp":"RoRo 육상전력이 자동차선 정박 배출을 줄인다.","eImp":"RoRo shore power cuts car-carrier at-berth emissions.","url":"https://shipandbunker.com/news/emea/930244-nyk-unit-launches-belgiums-first-roro-shore-power-facility"}]},{"code":"DIG","type":"news","kTitle":"Section 7. Digitalization","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"해상 사이버사고 2025년 103% 급증…스마트선박 표적","src":"SAFETY4SEA","date":"2026","kSum":"2025년 해상 사이버사고가 전년比 103% 급증했으며 DDoS·랜섬웨어·악성코드가 다수를 차지했다. CYTUR는 스마트선박이 표적이 되고 있다며 시큐어바이디자인 전환을 촉구했다.","eSum":"Maritime cyber incidents jumped 103% in 2025 - DDoS, ransomware and malware dominating - and CYTUR warned smart ships are under fire, urging a secure-by-design overhaul.","kImp":"연결성 확대가 공격면을 키워 OT 보안이 시급하다.","eImp":"Rising connectivity expands the attack surface, making OT security urgent.","url":"https://safety4sea.com/maritime-cyber-incidents-jumped-103-in-2025/"},{"code":"DIG","title":"2026 해상 사이버리스크, 운영 리스크로 격상","src":"Dryad Global","date":"2026","kSum":"2026년 해상 사이버리스크가 IT를 넘어 운영기술(OT)·선박시스템으로 확산되며 운영 리스크로 격상됐다. AI 기반 자율형 공격이 새로운 국면을 예고한다.","eSum":"Maritime cyber risk in 2026 has become an operational risk as threats spread beyond IT into OT and vessel systems, with AI-driven autonomous attacks signalling a new phase.","kImp":"사이버리스크가 안전·가동률에 직접 영향을 준다.","eImp":"Cyber risk now directly affects safety and uptime.","url":"https://channel16.dryadglobal.com/maritime-cyber-risk-in-2026"},{"code":"DIG","title":"AI 확산이 해운 사이버 공격 위험 키워","src":"Smart Maritime Network","date":"2026-03","kSum":"보고서에 따르면 AI 확산이 해운의 사이버 공격 위험을 키우고 있다. 공격 자동화·정교화로 방어 난도가 상승한다.","eSum":"A report finds AI is placing the maritime industry at greater risk of cyber-attack, as automation and sophistication raise the bar for defence.","kImp":"AI 양면성에 대응한 방어 투자가 필요하다.","eImp":"Defensive investment must address AI's double-edged nature.","url":"https://smartmaritimenetwork.com/2026/03/02/ai-is-placing-maritime-industry-at-greater-risk-of-cyber-attack-report/"},{"code":"DIG","title":"항행수역 디지털 트윈, e-내비게이션 길 연다","src":"IHO","date":"2026","kSum":"국제수로기구(IHO)는 항행수역 디지털 트윈이 e-내비게이션의 토대가 된다고 제시했다. 정밀 해도·실시간 데이터 연계로 항행 안전·효율을 높인다.","eSum":"The IHO outlines how a digital twin of navigable waters paves the way for e-navigation, improving safety and efficiency via precise charts and real-time data integration.","kImp":"데이터 표준화가 자율·지능형 항행의 전제다.","eImp":"Data standardisation underpins autonomous and intelligent navigation.","url":"https://iho.int/en/the-digital-twin-of-the-navigable-waters-paving-the-way-for-e-navigation"},{"code":"DIG","title":"2026 해상 사이버리스크: 선대·규제·보험사 대응","src":"Maritime Innovations","date":"2026","kSum":"2026년 해상 사이버리스크가 선대 운영·규제 준수·보험 인수 전반에 걸쳐 중요해지고 있다. 가시성·인증·책임소재 정립이 핵심 과제로 부상했다.","eSum":"Maritime cyber risk in 2026 matters across fleet operations, compliance and insurance underwriting, with visibility, certification and accountability emerging as key tasks.","kImp":"사이버 거버넌스가 보험·인증과 연계된다.","eImp":"Cyber governance is increasingly tied to insurance and certification.","url":"https://maritime-innovations.com/maritime-cyber-risk-2026/"},{"code":"DIG","title":"IMO, 자율운항선 안전코드 채택(5월 22일)","src":"Smart Maritime Network","date":"2026-05-22","kSum":"IMO가 5월 22일 첫 국제 자율운항선(MASS) 안전코드를 채택했다. 4단계 자율도와 원격운항 요건을 규정하며 7월 1일 비강제 발효한다.","eSum":"The IMO adopted the first international MASS safety code on 22 May, defining four degrees of autonomy and remote-operation requirements; it takes effect 1 July as a non-mandatory instrument.","kImp":"자율운항 표준화가 디지털 선박 투자를 촉진한다.","eImp":"Autonomy standards spur digital-ship investment.","url":"https://smartmaritimenetwork.com/2026/05/22/imo-adopts-international-safety-code-for-autonomous-ships/"},{"code":"DIG","title":"자율운항 코드, 상용 개념 실증과 함께 탄력","src":"Riviera","date":"2026","kSum":"자율운항선 코드가 확정되면서 상용 자율운항 개념의 실증이 실용적 속도로 진전되고 있다. 목적적합성(fit-for-purpose) 설계가 강조된다.","eSum":"With the MASS Code finalised, commercial autonomy concepts are proceeding at a practical pace, with emphasis on fit-for-purpose design.","kImp":"단계적 실증이 자율항법 신뢰성을 높인다.","eImp":"Phased demonstrations build trust in autonomy.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/autonomy-must-be-fit-for-purpose-as-mass-code-is-finalised-87840"},{"code":"DIG","title":"IMO 자율운항 코드, 무인 탱커 시대 길 열어","src":"GoShips","date":"2026","kSum":"분석에 따르면 IMO 자율운항 코드가 무인·소수인력 탱커 시대의 길을 열고 있으며, 선주들이 차세대 대형탱커 발주를 늘리고 있다.","eSum":"Analysis says the IMO's autonomy code is clearing the path for skeleton-crew tankers, with owners ordering next-generation supertankers.","kImp":"자율화가 선원 직무와 선대 경제성을 재편한다.","eImp":"Autonomy reshapes crew roles and fleet economics.","url":"https://www.gosships.com/p/the-imo-just-cleared-the-path-for"},{"code":"DIG","title":"마리타임테크리뷰: IMO 첫 글로벌 MASS 코드","src":"Maritime Technology Review","date":"2026-05-22","kSum":"IMO가 채택한 첫 글로벌 자율운항선(MASS) 코드가 디지털·원격운항 기술의 제도권 편입을 알렸다. 화물선 대상으로 7월 1일 발효된다.","eSum":"The IMO's first global MASS Code marks the institutional integration of digital and remote-operation technologies, effective 1 July for cargo ships.","kImp":"규범 정립이 디지털 항법 솔루션 확산을 견인한다.","eImp":"A formal code accelerates uptake of digital navigation solutions.","url":"https://maritimetechnologyreview.com/2026/05/22/imo-adopts-first-global-mass-code-for-autonomous-ships/"}]},{"code":"TECH","type":"news","kTitle":"Section 8. Ship Manager Technical Team","eTitle":"Section 8. Ship Manager Technical Team","items":[{"code":"TECH","title":"스크러버 개조, 계획 부재 시 공기 지연 위험","src":"Riviera","date":"2026","kSum":"스크러버 개조는 통상 21~28일이 소요되며 계획 부재 시 지연이 잦다. 2026~27년 1만2천여 척이 검사 대상에 올라 수리조선소 특별검사가 몰릴 전망이다.","eSum":"Scrubber retrofits typically take 21-28 days and often slip without planning; with over 12,000 vessels due for survey in 2026-27, repair yards face a rush of special surveys.","kImp":"드라이도크 일정·자재 사전계획이 가동손실을 줄인다.","eImp":"Pre-planned dry-dock slots and materials cut off-hire losses.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/staying-on-top-of-the-scrubber-retrofit-56583"},{"code":"TECH","title":"탱커 수리조선소, 개조 작업 급증","src":"Riviera","date":"2026","kSum":"탱커 수리조선소가 개조 작업 급증을 경험하고 있다. 배출규제·연료전환 대응 개조 수요가 도크 가용성을 압박한다.","eSum":"Tanker repair yards are experiencing a flurry of retrofit activity as emissions and fuel-transition upgrades pressure dock availability.","kImp":"개조 수요 급증이 도크 확보 경쟁을 심화한다.","eImp":"Surging retrofit demand intensifies competition for dock slots.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/tanker-repair-yards-experience-a-flurry-of-retrofit-activity-55810"},{"code":"TECH","title":"스크러버, 초기 도입 선사가 트렌드 주도","src":"Riviera","date":"2026","kSum":"스크러버 시장에서 초기 도입 선사들이 사양·운영 표준을 주도하고 있다. 데이터 기반 운영 최적화가 개조 ROI를 결정한다.","eSum":"Early adopters are setting the trend in scrubbers, shaping specs and operating standards; data-driven optimisation determines retrofit ROI.","kImp":"운영 데이터 관리가 개조 투자 회수를 좌우한다.","eImp":"Operating-data management drives retrofit payback.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/early-adopters-set-the-trend-in-scrubbers-56220"},{"code":"TECH","title":"드라이도크 개조, 정비·탈탄소 트렌드 부상(MOL 사례)","src":"MOL Service","date":"2026","kSum":"선박 수리 도크에서 정비·개조·탈탄소 작업이 늘고 있으며 MOL 사례가 소개됐다. 계획정비·연료전환 개조·에너지절감장치(ESD) 설치가 도크 일정의 핵심으로 부상한다.","eSum":"Ship-repair docks see growing maintenance, retrofit and decarbonization work — illustrated by MOL cases — with planned maintenance, fuel-transition retrofits and energy-saving-device installs central to dock scheduling.","kImp":"드라이도크 통합 계획이 가동손실·비용을 줄인다.","eImp":"Integrated dry-dock planning cuts off-hire and cost.","url":"https://www.mol-service.com/blog/dry-dock-retrofit"},{"code":"TECH","title":"EU FIT-HORIZONS, 기존 선대 개조 설계환경 개발","src":"MarineLink","date":"2026","kSum":"EU가 약 461만달러를 투입한 FIT-HORIZONS 프로젝트가 19개 해사기업과 함께 지능형 개조 설계환경을 개발한다. 대체연료·전기화·풍력보조·공기윤활·선체개조를 동시 평가한다.","eSum":"The EU-funded FIT-HORIZONS project (~US$4.61M) brings 19 maritime firms together to build an intelligent retrofit design environment evaluating alternative fuels, electrification, wind assist, air lubrication and hull mods.","kImp":"통합 개조 설계가 탈탄소 투자 효율을 높인다.","eImp":"Integrated retrofit design improves decarbonization ROI.","url":"https://www.marinelink.com/news/european-fithorizons-project-aims-540202"},{"code":"TECH","title":"DH조선, VLGC 독립형 Type-B 탱크 설계 승인 획득","src":"Container News","date":"2026","kSum":"DH조선(DH Shipbuilding)이 VLGC용 독립형 Type-B 화물탱크 설계 승인을 받아 가스운반선 시장에 진입한다. 기술 검증이 신규 수주 기반을 넓힌다.","eSum":"DH Shipbuilding entered the VLGC market with design approvals for an independent Type-B cargo tank, broadening its order base through technical validation.","kImp":"설계 검증이 기술관리·신조 경쟁력을 강화한다.","eImp":"Design validation strengthens technical and newbuild competitiveness.","url":"https://container-news.com/dh-shipbuilding-enters-vlgc-market-with-new-vessel-design-approvals/"},{"code":"TECH","title":"머스크탱커스, ZeroNorth와 5년·240척 디지털 파트너십","src":"Smart Maritime Network","date":"2026","kSum":"머스크탱커스가 ZeroNorth와 240척 규모의 5년 디지털 파트너십을 갱신·확대했다. 항해 최적화·선체오손·기관 효율 모니터링으로 연료비를 절감한다.","eSum":"Maersk Tankers renewed and expanded a five-year ZeroNorth partnership covering 240 vessels, using voyage optimisation and hull/machinery monitoring to cut fuel costs.","kImp":"디지털 선대관리가 기술팀 운영효율을 높인다.","eImp":"Digital fleet management lifts technical-team efficiency.","url":"https://smartmaritimenetwork.com/2026/01/05/maersk-tankers-renews-zeronorth-partnership/"},{"code":"TECH","title":"에너지절감장치(ESD), 2~15% 효율 개선 기대","src":"MarineLink","date":"2026","kSum":"에너지절감장치(ESD)가 선형·운항프로파일에 따라 2~15%의 효율 개선을 제공해 연료비 절감과 선대 효율을 동시에 높인다. 개조 수요가 늘고 있다.","eSum":"Energy-saving devices offer 2-15% efficiency gains depending on hull and operating profile, cutting fuel costs and lifting fleet efficiency amid rising retrofit demand.","kImp":"ESD 투자 회수가 개조 우선순위를 결정한다.","eImp":"ESD payback determines retrofit priorities.","url":"https://www.marinelink.com/news/maritime/energy-saving-devices"},{"code":"TECH","title":"선대관리 소프트웨어, 기술관리 디지털화 가속","src":"MarineLink","date":"2026","kSum":"선대관리 소프트웨어 도입이 확산되며 기술관리의 디지털화가 가속되고 있다. 계획정비·상태기반정비·규제 보고가 통합 플랫폼으로 수렴한다.","eSum":"Adoption of fleet-management software is accelerating the digitalisation of technical management, converging planned/condition-based maintenance and regulatory reporting onto integrated platforms.","kImp":"데이터 통합이 정비·보고 효율을 높인다.","eImp":"Data integration improves maintenance and reporting efficiency.","url":"https://www.marinelink.com/news/maritime/fleet-management-software"}]},{"code":"HR","type":"news","kTitle":"Section 9. Marine HR","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"2026 선원 최저임금, ITF/ILO 새 기준 적용","src":"Seaplify","date":"2026","kSum":"2026년 선원 최저임금이 ITF/ILO 합의에 따라 인상 적용된다. AB 기준 월 최저임금이 단계적으로 오르며 MLC 2006이 이를 참조한다.","eSum":"Seafarer minimum wages for 2026 rise under new ITF/ILO rates, with the AB monthly floor stepping up and referenced by MLC 2006.","kImp":"최저임금 인상이 인건비 기준선을 끌어올린다.","eImp":"Minimum-wage increases lift the baseline for crew costs.","url":"https://blog.seaplify.com/seafarer-minimum-wage-2026/"},{"code":"HR","title":"선원 부족이 임금 상승 견인","src":"Marine Log","date":"2026","kSum":"간부 선원 부족이 임금 상승을 견인하고 있다. 기관장·1등항해사·전자기관사 등 핵심 직책의 보수가 빠르게 오른다.","eSum":"Crew shortages are driving up seafarer wages, with senior roles - Chief Engineers, Chief Officers, ETOs - seeing the fastest pay rises.","kImp":"인력난이 운영비·확보경쟁을 동시에 키운다.","eImp":"Scarcity raises both opex and the contest for talent.","url":"https://www.marinelog.com/news/crew-shortages-are-driving-up-seafarer-wages/"},{"code":"HR","title":"도쿄·파리 MOU 선원임금 CIC 베스트프랙티스","src":"SAFETY4SEA","date":"2026","kSum":"도쿄·파리 MOU의 선원임금·고용계약(SEA) 집중점검(CIC)에 대비한 베스트프랙티스 가이드가 제시됐다. 임금 지급·계약·근로조건 기록 정비를 강조한다.","eSum":"A best-practice guide for the Tokyo/Paris MoU CIC on crew wages and SEAs highlights proper documentation of wage payment, contracts and working conditions.","kImp":"임금·계약 기록 관리가 PSC 리스크를 줄인다.","eImp":"Wage/contract recordkeeping reduces PSC risk.","url":"https://safety4sea.com/cm-cic-on-crew-wages-and-seafarer-employment-agreement-a-best-practice-guide/"},{"code":"HR","title":"선원 복지, 글로벌 개혁으로 강화","src":"Ship Universe","date":"2026","kSum":"새로운 글로벌 개혁으로 선원 복지가 강화되고 있다. 근로·휴식·송환·웰빙 보호가 강화되며 인력 유지·확보에 기여한다.","eSum":"New global reforms are boosting seafarer welfare, strengthening protections on work/rest, repatriation and wellbeing, aiding retention and recruitment.","kImp":"복지 강화가 인력난 완화의 핵심 수단이다.","eImp":"Better welfare is key to easing crew shortages.","url":"https://www.shipuniverse.com/news/seafarer-welfare-gets-boost-from-new-global-reforms/"},{"code":"HR","title":"해사부문 멘토링 프로그램의 중요성 부각","src":"Seatrade Maritime","date":"2026","kSum":"해사부문에서 멘토링 프로그램의 중요성이 부각되고 있다. 신임 사관·생도의 적응과 정착을 도와 이직을 줄인다.","eSum":"Mentoring programmes are gaining importance in the maritime sector, helping new officers and cadets adapt and stay, reducing attrition.","kImp":"멘토링이 신규 인력 정착률을 높인다.","eImp":"Mentoring improves retention of new entrants.","url":"https://www.seatrade-maritime.com/crewing/the-importance-of-mentoring-programmes-in-the-maritime-sector"},{"code":"HR","title":"Tapiit Live, 선원 정신건강 라이브 교육 출시","src":"Seatrade Maritime","date":"2026","kSum":"Tapiit Live가 선원 정신건강 라이브 교육 과정을 출시한다. 원격 실시간 교육으로 선상 고립·스트레스 대응 역량을 키운다.","eSum":"Tapiit Live is launching live seafarer mental-health training courses, using remote real-time sessions to build coping skills against isolation and stress.","kImp":"정신건강 교육이 안전·복지 성과를 개선한다.","eImp":"Mental-health training improves safety and welfare outcomes.","url":"https://www.seatrade-maritime.com/crewing/tapiit-live-to-launch-seafarer-mental-health-live-training-courses"},{"code":"HR","title":"STCW 2026 개정, '폭력·괴롭힘 예방' 역량 신설","src":"JobMarineMan","date":"2026","kSum":"2026년 1월 1일부터 STCW 표 A-VI/1-4에 '폭력·괴롭힘의 예방과 대응' 역량이 신설됐다. 기본안전교육(PSSR) 요건이 강화된다.","eSum":"From 1 January 2026, STCW Table A-VI/1-4 introduces the competence 'contribute to the prevention of and response to violence and harassment', strengthening basic safety training (PSSR).","kImp":"교육 요건 강화가 선상 문화·안전을 개선한다.","eImp":"Stronger training requirements improve onboard culture and safety.","url":"https://jobmarineman.com/marine-log/stcw-basic-safety-training-2026-what-changes/"},{"code":"HR","title":"세일러스소사이어티, 2025/26 생도 보고서 발간","src":"NorthStandard","date":"2026","kSum":"세일러스 소사이어티(Sailors' Society) 생도 보고서 2025/26이 발간됐다. 생도의 고립·스트레스·피로 문제와 대응 역량 부족을 짚었다.","eSum":"The Sailors' Society Cadet Report 2025/26 was published, highlighting cadets' struggles with isolation, stress and fatigue and a lack of coping confidence.","kImp":"생도 지원 강화가 미래 인력 확보의 토대다.","eImp":"Stronger cadet support underpins future workforce supply.","url":"https://north-standard.com/insights-and-resources/resources/news/sailors-society-cadet-report-202526"},{"code":"HR","title":"노틸러스: 더 나은 해사 일터를 향한 선원 복지","src":"Nautilus International","date":"2026","kSum":"노틸러스 인터내셔널이 더 나은 해사 일터를 위한 선원 복지 과제를 제시했다. 근로조건·연결성·존엄 보장이 인력 유지의 핵심으로 지목됐다.","eSum":"Nautilus International set out seafarer-welfare priorities toward a better maritime workplace, citing working conditions, connectivity and dignity as central to retention.","kImp":"일터 개선이 숙련 인력 이탈을 막는다.","eImp":"Workplace improvements stem the loss of skilled crew.","url":"https://www.nautilusint.org/en/news-insight/telegraph/seafarer-welfare-towards-a-better-maritime-workplace/"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"육상 리더십이 선상 안전문화를 좌우","src":"SAFETY4SEA","date":"2026","kSum":"2026 SAFETY4SEA 리마솔 포럼에서 육상 리더십의 질이 선상 안전문화를 근본적으로 형성한다는 점이 강조됐다. 일관된 메시지와 자원지원이 핵심으로 지목됐다.","eSum":"At the 2026 SAFETY4SEA Limassol Forum, speakers stressed that the quality of shore leadership fundamentally shapes onboard safety culture, with consistent messaging and resourcing key.","kImp":"경영진의 안전 우선순위가 현장 행동을 바꾼다.","eImp":"Management's safety priorities change frontline behaviour.","url":"https://safety4sea.com/cm-effective-leadership-ashore-improves-safety-culture-onboard/"},{"code":"HSEQ","title":"교훈: 밀폐구역 출입 통제를 강화하라","src":"SAFETY4SEA","date":"2026","kSum":"사고 교훈으로 밀폐구역 출입 통제 강화가 제시됐다. 진입 전 가스측정·허가서·감시인 배치 등 절차 준수가 인명사고를 막는 핵심이다.","eSum":"A lessons-learned note urges enhanced control over enclosed-space entry - pre-entry gas testing, permits and a posted attendant are central to preventing fatalities.","kImp":"비가시 위험에 대한 절차 준수가 생명을 지킨다.","eImp":"Procedural discipline against unseen hazards saves lives.","url":"https://safety4sea.com/lessons-learned-enhance-the-control-over-enclosed-space-entry/"},{"code":"HSEQ","title":"교훈: 더 안전한 계류로 인명을 지켜라","src":"SAFETY4SEA","date":"2026","kSum":"계류 작업 중 스냅백 존 회피와 안전한 위치 선정의 중요성이 재차 강조됐다. 라인 장력·배치 관리와 교육이 계류사고를 줄인다.","eSum":"Safer mooring guidance reiterates avoiding snap-back zones and choosing safe positions; managing line tension/layout and training reduces mooring casualties.","kImp":"계류 위험구역 인식과 절차가 부상을 예방한다.","eImp":"Awareness of mooring danger zones and procedure prevents injuries.","url":"https://safety4sea.com/cm-saving-lives-through-safer-mooring/"},{"code":"HSEQ","title":"쉽오너스 P&I, 손실예방·어선 안전 발간물 발행","src":"IIMS","date":"2026","kSum":"쉽오너스(Shipowners) P&I 클럽이 손실예방과 어선 안전을 다룬 발간물을 발행했다. 소형선·어선의 흔한 사고 유형과 예방 조치를 정리했다.","eSum":"The Shipowners' P&I Club issued a loss-prevention and fishing-vessel safety publication, summarising common small-craft incidents and preventive measures.","kImp":"손실예방 자료가 소형선 사고 저감에 기여한다.","eImp":"Loss-prevention material helps cut small-craft incidents.","url":"https://www.iims.org.uk/shipowners-pi-club-issues-loss-prevention-fishing-vessel-safety-publication/"},{"code":"HSEQ","title":"Gard, 브리지 시스템 손실예방 지식 공유","src":"Riviera","date":"2026","kSum":"Gard가 브리지(선교) 시스템 관련 손실예방 지식을 공유했다. ECDIS·경보관리·당직 인적요소 등 항해사고 예방 포인트를 짚었다.","eSum":"Gard shared loss-prevention knowledge on bridge systems, covering ECDIS, alarm management and watchkeeping human factors.","kImp":"브리지 인적요소 관리가 항해사고를 줄인다.","eImp":"Managing bridge human factors reduces navigational incidents.","url":"https://www.rivieramm.com/news-content-hub/gard-shares-loss-prevention-knowledge-on-bridge-systems-88088"},{"code":"HSEQ","title":"Gard·NAVTOR, 손실예방 콘텐츠를 NavStation에 통합","src":"MarineLink","date":"2026","kSum":"Gard와 NAVTOR가 Gard 손실예방 콘텐츠를 항해계획 플랫폼 NavStation에 통합했다. 선원이 항해 중 안전 가이드에 손쉽게 접근하도록 한다.","eSum":"Gard and NAVTOR integrated Gard's loss-prevention content into the NavStation platform, giving crews easier access to safety guidance at sea.","kImp":"현장 접근성 향상이 안전관리 실효성을 높인다.","eImp":"Better at-sea access improves safety-management effectiveness.","url":"https://www.marinelink.com/news/gard-navtor-integrate-loss-prevention-536831"},{"code":"HSEQ","title":"브리타니아 P&I, 항해·조선 손실예방 가이드 제공","src":"Britannia P&I","date":"2026","kSum":"브리타니아(Britannia) P&I가 항해·조선 사고 원인 분석을 바탕으로 손실예방 가이드를 제공한다. ECDIS 설정·좌초예방·도선사 동승 시 선장 책임 등을 다룬다.","eSum":"Britannia P&I provides navigation and manoeuvring loss-prevention guidance, covering ECDIS setup, grounding prevention and master-pilot responsibilities.","kImp":"항해 손실예방이 좌초·충돌 클레임을 줄인다.","eImp":"Navigation loss prevention reduces grounding/collision claims.","url":"https://britanniapandi.com/topic/navigation-manoeuvring/"},{"code":"HSEQ","title":"스팀십뮤추얼, 냉동화물 손실예방 핵심 점검","src":"Steamship Mutual","date":"2026","kSum":"스팀십뮤추얼(Steamship Mutual)이 냉동(reefer)화물 손실예방의 핵심 사항을 안내했다. 온도·습도·통풍 관리와 적절한 취급·기록의 중요성을 강조했다.","eSum":"Steamship Mutual outlined key aspects of preventing reefer-cargo losses, stressing temperature/humidity/airflow control and proper handling.","kImp":"냉동화물 관리가 클레임·품질손실을 줄인다.","eImp":"Reefer-cargo control reduces claims and quality losses.","url":"https://www.steamshipmutual.com/loss-prevention"},{"code":"HSEQ","title":"비상훈련, 2026 SOLAS 요건과 모범사례","src":"Marine Inspection","date":"2026","kSum":"선상 비상훈련의 2026년 SOLAS 요건과 모범사례가 정리됐다. 월 1회 소화·퇴선 훈련, 분기별 구명정 진수 등 훈련 기록이 PSC·ISM 점검의 핵심이다.","eSum":"Shipboard emergency drills and 2026 SOLAS requirements were summarised - monthly fire/abandon-ship drills and quarterly lifeboat launches, with records central to PSC/ISM checks.","kImp":"훈련 기록 관리가 점검 적합성을 좌우한다.","eImp":"Drill-record management drives inspection compliance.","url":"https://marineinspection.app/article/shipboard-emergency-drills-solas-requirements-best-practices"}]},{"code":"KR","type":"news","kTitle":"Section 11. Korean Shipping Market","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR","title":"조선 빅3 동반 강세…수주 기대감 확산","src":"CBC News (씨비씨뉴스)","date":"2026","kSum":"한화오션(Hanwha Ocean)·삼성중공업(Samsung Heavy)·HD현대중공업(HD Hyundai Heavy)이 수주 기대감에 동반 강세를 보였다. 친환경 선박 전환과 방산 성장 기대가 매수세를 유인했다.","eSum":"Hanwha Ocean, Samsung Heavy and HD Hyundai Heavy rose together on order expectations, drawing buying on green-ship transition and defense growth hopes.","kImp":"수주 모멘텀이 조선주 전반의 투자심리를 견인한다.","eImp":"Order momentum drives sentiment across shipbuilding stocks.","url":"https://www.cbci.co.kr/news/articleView.html?idxno=582566"},{"code":"KR","title":"현대글로비스, 하반기 실적 우상향 기대","src":"In The News (인더리포트)","date":"2026","kSum":"자동차운반선 시황 호조와 컨테이너 운임 상승으로 현대글로비스(Hyundai Glovis)의 하반기 실적이 우상향할 가능성이 크다고 분석됐다. 운송 섹터 기대가 커지고 있다.","eSum":"Strong car-carrier markets and rising container rates point to upside for Hyundai Glovis in H2, lifting expectations across the transport sector.","kImp":"PCTC·컨테이너 동반 강세가 물류기업 실적을 끌어올린다.","eImp":"Concurrent PCTC and box strength boost logistics earnings.","url":"https://www.inthenews.co.kr/news/article.html?no=87539"},{"code":"KR","title":"HMM 매각, 운임 변동성 속 장기화 전망","src":"Shipping News Net (쉬핑뉴스넷)","date":"2026","kSum":"트럼프발 운임 변동성 속에서 HMM 매각이 장기화될 것이라는 관측이 제기됐다. 시황 불확실성이 매각 가격·시점에 영향을 준다.","eSum":"Amid Trump-driven rate volatility, HMM's sale is expected to take a long time, with market uncertainty affecting price and timing.","kImp":"매각 불확실성이 국적선사 전략에 변수로 작용한다.","eImp":"Sale uncertainty is a wildcard for the national carrier's strategy.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=64090"},{"code":"KR","title":"HMM, 美 파산 생활용품업체로부터 피소","src":"The Guru (더구루)","date":"2026","kSum":"HMM이 파산한 미국 대형 생활용품업체로부터 화물 운송 지연·부당 운임을 이유로 피소됐다. 운임 분쟁이 법적 리스크로 비화했다.","eSum":"HMM was sued by a bankrupt large US household-goods firm alleging shipping delays and unfair freight, turning a rate dispute into legal risk.","kImp":"운임 분쟁이 선사 법적·평판 리스크로 확대된다.","eImp":"Freight disputes expand into legal and reputational risk for carriers.","url":"https://www.theguru.co.kr/news/article.html?no=96536"},{"code":"KR","title":"HMM 본사, 서울→부산 이전 확정","src":"Bizwatch (비즈워치)","date":"2026-05","kSum":"2026년 5월 HMM(에이치엠엠) 본사의 서울에서 부산 이전이 확정됐다. 핵심 기능의 동반 이전 여부가 업계 관심사로 떠올랐다.","eSum":"HMM's headquarters relocation from Seoul to Busan was confirmed in May 2026, raising industry questions over whether core functions will move too.","kImp":"본사 이전이 부산 해운클러스터 강화로 이어진다.","eImp":"The HQ move bolsters the Busan shipping cluster.","url":"https://news.bizwatch.co.kr/article/industry/2026/05/06/0040"},{"code":"KR","title":"해상운임 상승에 해운주 동반 강세…HMM 5%대","src":"Investing.com (인베스팅)","date":"2026-06","kSum":"해상운임 상승으로 해운주가 동반 강세를 보이며 HMM(에이치엠엠)이 5%대 상승했다. 운임 모멘텀이 투자심리를 자극했다.","eSum":"Rising freight rates lifted shipping stocks, with HMM up around 5%, as rate momentum stoked investor sentiment.","kImp":"운임 사이클이 국적선사 주가를 좌우한다.","eImp":"The rate cycle drives national carriers' share prices.","url":"https://kr.investing.com/news/stock-market-news/article-1105251"},{"code":"KR","title":"해운주 강세: STX그린로지스·흥아·대한해운·팬오션·HMM","src":"Finomy (현대경제신문)","date":"2026","kSum":"STX그린로지스·흥아해운(Heung-A)·대한해운(Korea Line)·팬오션(Pan Ocean)·HMM 등 해운 관련주가 동반 강세를 보였다. 운임·시황 개선 기대가 반영됐다.","eSum":"Korean shipping stocks - STX Green Logis, Heung-A, Korea Line, Pan Ocean and HMM - rose together on expectations of improving rates and market conditions.","kImp":"시황 기대가 해운주 전반에 매수세를 부른다.","eImp":"Market optimism draws buying across shipping stocks.","url":"http://www.finomy.com/news/articleView.html?idxno=252391"},{"code":"KR","title":"KOBC, 저탄소 친환경선박 지원사업 신청기간 연장","src":"KOBC (한국해양진흥공사)","date":"2026","kSum":"한국해양진흥공사(KOBC)가 2026년 저탄소·친환경선박 정책 대응 지원사업 신청기간을 연장했다. 친환경 인증선 건조에 8~10% 보조금을 지원하며 30척 지원을 목표로 한다.","eSum":"KOBC extended applications for its 2026 low-carbon green-ship support scheme, offering 8-10% subsidies for certified green newbuilds with a target of 30 vessels.","kImp":"정책금융이 국적선사 친환경 전환을 뒷받침한다.","eImp":"Policy finance supports national carriers' green transition.","url":"https://kobc.or.kr/ebz/kor/bbs/view.do?mId=0202000000&ptIdx=251&bIdx=97383"},{"code":"KR","title":"KOBC, 2030 비전…불확실성 속 경쟁력 강화","src":"Dailian (데일리안)","date":"2026","kSum":"한국해양진흥공사(KOBC)가 2030 비전을 통해 불확실한 시황 속에서 국적선사 경쟁력 강화 기회를 모색한다고 밝혔다. 친환경·디지털 전환 지원을 확대한다.","eSum":"KOBC outlined a 2030 vision to turn market uncertainty into a chance to strengthen national carriers' competitiveness, expanding green and digital transition support.","kImp":"정책기관의 전략이 해운 산업 방향을 제시한다.","eImp":"The agency's strategy signals the industry's direction.","url":"https://www.dailian.co.kr/news/view/1262748"}]},{"code":"INS","type":"news","kTitle":"Section 12. Marine Insurance (P&I / H&M)","eTitle":"Section 12. Marine Insurance (P&I / H&M)","items":[{"code":"INS","title":"로이즈, 호르무즈 전쟁위험 신규 컨소시엄 출범","src":"Lloyd's","date":"2026-06-19","kSum":"로이즈가 호르무즈 해협 통항 선박·화물에 추가 전쟁위험 인수능력을 제공하는 신규 컨소시엄을 출범했다. 처브(Chubb) 주간사로 선체·P&I 각 2억달러, 화물 2억달러 능력을 제공한다.","eSum":"Lloyd's launched a new market consortium providing extra marine war-risk capacity for Hormuz transits - Chubb as lead, offering up to US$200M each for hull and P&I plus US$200M for cargo.","kImp":"민간 인수능력 보강이 통항 재개를 뒷받침한다.","eImp":"Added private capacity supports a resumption of transits.","url":"https://www.lloyds.com/insights/media-centre/press-releases/press-release-19062026"},{"code":"INS","title":"호르무즈 전쟁보험 경색…중동전 격화 반영","src":"S&P Global","date":"2026-03","kSum":"중동 전쟁 격화로 호르무즈 해협 전쟁보험 인수가 사실상 고갈됐다고 S&P 글로벌이 보도했다. 인수 거부와 보험료 급등이 동시에 나타났다.","eSum":"Marine war insurance for Hormuz dried up as Middle East conflict intensified, with both withdrawal of cover and soaring premiums.","kImp":"보험 가용성 위축이 항행·무역에 직접 타격을 준다.","eImp":"Shrinking cover availability directly hits navigation and trade.","url":"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2026/3/marine-war-insurance-for-hormuz-dries-up-as-middle-east-war-intensifies-99283143"},{"code":"INS","title":"전쟁위험 보험료, 선가의 2.5~3%…평시의 25~30배","src":"House of Saud","date":"2026-06","kSum":"호르무즈 위험 완화에도 전쟁위험 보험료는 항차당 선가의 2.5~3%로 평시 기준(0.1%)의 25~30배 수준을 유지하고 있다. 시장은 위험 완화를 즉시 반영하지 않는다.","eSum":"Despite some de-escalation, war-risk premiums remain at 2.5-3% of hull value per voyage - 25-30x the 0.1% pre-conflict baseline - as the market lags risk improvement.","kImp":"보험료 경직성이 운임·연료 비용 부담을 가중한다.","eImp":"Sticky premiums add to freight and fuel cost burdens.","url":"https://houseofsaud.com/hormuz-downgrade-insurance-market-gap/"},{"code":"INS","title":"WEF: 중동전, 정부를 '최후 보험자'로 만들다","src":"World Economic Forum","date":"2026-04","kSum":"세계경제포럼은 호르무즈 전쟁보험 중단이 정부를 사실상 최후 보험자로 만들고 있다고 분석했다. 국가 보증·재보험 개입 필요성이 부각된다.","eSum":"The WEF analyses how the halt in Hormuz war-risk insurance is turning governments into insurers of last resort, highlighting the need for state guarantees and reinsurance backstops.","kImp":"공적 백스톱이 해상무역 연속성의 안전판이 된다.","eImp":"Public backstops become a safety net for trade continuity.","url":"https://www.weforum.org/stories/2026/04/how-middle-east-war-turning-governments-into-insurers-last-resort/"},{"code":"INS","title":"LMA: 통항 감소는 보험가용성 아닌 안전우려 탓","src":"LMA","date":"2026-06","kSum":"런던보험시장협회(LMA)는 호르무즈 통항 감소의 주원인이 보험 가용성이 아니라 안전 우려라고 밝혔다. 위험구역 담보는 시장에서 제공되고 있다는 입장이다.","eSum":"The LMA states that reduced Strait of Hormuz traffic is driven by safety concerns rather than insurance availability, noting cover for high-risk areas is being offered.","kImp":"리스크 인식이 보험보다 통항 결정을 좌우한다.","eImp":"Risk perception, more than insurance, drives transit decisions.","url":"https://lmalloyds.com/safety-concerns-not-insurance-availability-driving-reduced-vessel-traffic-in-the-strait-of-hormuz/"},{"code":"INS","title":"하우든, 호르무즈 전쟁위험 담보 제공 지속","src":"Howden Group","date":"2026","kSum":"하우든(Howden)은 호르무즈 해협 고위험 구역 선박에 전쟁위험 담보를 제공하는 시장이 작동 중이라고 밝혔다. 가격은 높지만 인수능력은 존재한다는 설명이다.","eSum":"Howden says the marine war market is offering cover for vessels in the high-risk Strait of Hormuz area - capacity exists, albeit at elevated pricing.","kImp":"고가라도 담보 존재가 통항 옵션을 유지시킨다.","eImp":"Cover, even if costly, keeps transit options open.","url":"https://www.howdengroupholdings.com/insights/strait-of-hormuz-marine-war-market-offering-cover-for-vessels-in-high-risk-areas"},{"code":"INS","title":"걸프 전쟁위험 담보 취소…에너지 비용 우려","src":"Al Jazeera","date":"2026-03-03","kSum":"보험사들이 페르시아만 전쟁위험 담보를 취소하면서 에너지 비용 상승 우려가 제기됐다. P&I 클럽들도 3월 5일자로 걸프 전쟁위험 담보를 취소했다.","eSum":"Insurers cancelled Gulf war-risk cover, raising fears of higher energy costs; P&I clubs also withdrew Persian Gulf war-risk cover effective 5 March.","kImp":"담보 취소가 에너지·운임 인플레로 전이된다.","eImp":"Cover withdrawal feeds into energy and freight inflation.","url":"https://www.aljazeera.com/economy/2026/3/3/maritime-insurers-cancel-war-risk-cover-in-gulf-will-it-spike-energy-cost"},{"code":"INS","title":"로이즈·처브, 호르무즈에 4억달러 전쟁위험 시설 출범","src":"OilPrice","date":"2026-06","kSum":"로이즈와 처브(Chubb)가 호르무즈 통항 재개를 돕기 위해 4억달러 규모 해상 전쟁위험 보험 시설을 출범했다. 선체·P&I·화물 위험에 별도 담보를 제공한다.","eSum":"Lloyd's and Chubb launched a US$400M marine war-risk facility to help vessels and cargo resume Hormuz transits, with separate cover for hull, P&I and cargo risks.","kImp":"대규모 인수능력이 통항 정상화를 촉진한다.","eImp":"Large capacity facilitates a return to normal transits.","url":"https://oilprice.com/Energy/Energy-General/Insurers-Roll-Out-400-Million-War-Risk-Facility-for-Hormuz-Shipping.html"},{"code":"INS","title":"로이즈 언더라이터, 호르무즈 재개 6대 우선과제 제시","src":"TradeWinds","date":"2026-06","kSum":"로이즈 언더라이터들이 호르무즈 해협 재개와 관련해 제재 명확화 등 6대 우선과제를 제시했다. 보험 담보 재개를 위한 전제조건을 정리했다.","eSum":"Lloyd's underwriters outlined six priorities as the Strait of Hormuz reopens, including clarity on sanctions, as preconditions for restoring cover.","kImp":"제재 명확화가 담보 재개의 핵심 조건이다.","eImp":"Sanctions clarity is key to restoring cover.","url":"https://www.tradewindsnews.com/insurance/lloyd-s-underwriters-outline-six-priorities-as-strait-of-hormuz-reopens/2-1-2006576"}]},{"code":"VET","type":"news","kTitle":"Section 13. Vetting / RightShip","eTitle":"Section 13. Vetting / RightShip","items":[{"code":"VET","title":"라이트십, 4월1일부터 노후 벌크선 점검 의무 강화","src":"RightShip","date":"2026","kSum":"2026년 4월 1일부터 선령 12년 이상 벌크·일반화물선이 유효한 라이트십(RightShip) 점검이 없으면 안전점수가 5점 만점 2점으로 강등돼 주요 화주의 용선에서 사실상 배제된다.","eSum":"From 1 April 2026, dry-bulk and general-cargo ships aged 12+ without a valid RightShip inspection are downgraded to a Safety Score of 2/5, effectively blocking nominations by major charterers.","kImp":"점검 미보유 선박의 상업적 배제 위험이 커진다.","eImp":"Ships lacking inspections face growing commercial exclusion.","url":"https://marineinspection.app/blog/rightship-vessel-vetting-safety-score-inspection-guide-bulk-carriers"},{"code":"VET","title":"라이트십, 7월1일 3단계…선령 11년+ 점검 요구","src":"RightShip","date":"2026","kSum":"라이트십 점검 요건 3단계가 2026년 7월 1일 시행돼 선령 11년 이상 선박도 유효한 점검을 요구받는다. 안전점수·PSC 결함 가중·GHG 등급이 종합 평가된다.","eSum":"RightShip's Phase 3 from 1 July 2026 extends inspection requirements to vessels aged 11+, with Safety Score, severity-weighted PSC deficiencies and GHG Rating jointly assessed.","kImp":"점검 요건 단계적 확대가 선대 관리 부담을 키운다.","eImp":"Phased inspection rules increase fleet-management burden.","url":"https://help.rightship.com/en/articles/rightships-safety-score-and-vessel-vetting"},{"code":"VET","title":"라이트십 GHG 등급, 상업적 차별화 요소로 부상","src":"RightShip","date":"2026","kSum":"라이트십 GHG 등급(A~G)이 EU ETS·FuelEU 확대 속에서 단순 환경배지를 넘어 상업적 차별화 요소로 부상하고 있다. ESG 화주의 용선 기준에 반영된다.","eSum":"RightShip's GHG Rating (A-G) is becoming a commercial differentiator - not just an environmental badge - as EU ETS and FuelEU expand and ESG charterers weigh it in chartering.","kImp":"GHG 등급이 용선 경쟁력과 직결된다.","eImp":"The GHG Rating ties directly to chartering competitiveness.","url":"https://rightship.com/solutions/charterer/safety-score"},{"code":"VET","title":"SIRE 2.0, 사진 중심·디지털 점검 정착","src":"OCIMF SIRE 2.0","date":"2026","kSum":"OCIMF SIRE 2.0 탱커 점검이 사진 중심·디지털 기록 체계로 정착되고 있다. 점검당 약 100개 맞춤 질문과 표준 사진 가이드라인이 적용된다.","eSum":"OCIMF SIRE 2.0 tanker inspections are bedding in as a photo-centric, digitally recorded regime, with ~100 tailored questions per inspection and standardised photo guidelines.","kImp":"사진·디지털 증빙 준비가 점검 통과의 변수다.","eImp":"Photo and digital evidence readiness is now a passing factor.","url":"https://marineinspection.app/blog/sire-2-0-inspection-guide-ocimf-tanker-vetting-programme-2026"},{"code":"VET","title":"라이트십 RISQ 3.2, 2월 25일부 전면 적용","src":"MaritimeCyprus","date":"2026-02","kSum":"2026년 2월 25일부터 모든 라이트십 점검이 RISQ 3.2 기준으로 시행된다. 30개 문항 통폐합 등 150여 개 조정으로 점검시간을 약 2시간 단축했다.","eSum":"From 25 February 2026, all RightShip inspections follow RISQ 3.2; over 150 adjustments, including consolidating/removing 30 questions, cut inspection time by ~2 hours.","kImp":"점검 효율화가 선사 부담을 다소 완화한다.","eImp":"A streamlined questionnaire eases owner burden somewhat.","url":"https://maritimecyprus.com/2026/02/10/maritime-update-rightship-inspection-ship-questionnaire-risq-3-2-in-effect-25-feb-2026/"},{"code":"VET","title":"SAFETY4SEA: 라이트십 점검, RISQ 3.2 기준 시행","src":"SAFETY4SEA","date":"2026","kSum":"라이트십 점검이 RISQ 3.2 기준에 따라 시행된다고 안내됐다. 밀폐구역·소화·해치커버·파일럿사다리 등 고위험 항목이 빈번한 지적 대상이다.","eSum":"RightShip inspections are now conducted under RISQ 3.2, with high-risk items such as enclosed space, firefighting, hatch covers and pilot ladders among the most frequently observed.","kImp":"고위험 항목 대비가 점검 성과를 좌우한다.","eImp":"Preparing high-risk items drives inspection outcomes.","url":"https://safety4sea.com/rightship-inspections-conducted-in-accordance-with-risq-3-2/"},{"code":"VET","title":"라이트십, RISQ 3.2 개정 심층 해설","src":"RightShip","date":"2026","kSum":"라이트십이 RISQ 3.2 개정과 점검 개선 사항을 심층 해설했다. 22개 협회·240여 건의 의견을 반영해 명확성·일관성을 높였다.","eSum":"RightShip published a deep dive on the RISQ 3.2 update and inspection improvements, incorporating input from 22 associations and 240+ submissions to boost clarity and consistency.","kImp":"업계 의견 반영이 점검 신뢰성을 높인다.","eImp":"Industry input strengthens inspection credibility.","url":"https://rightship.com/insights/deep-dive-advancing-vessel-safety-update-risq-3.2-and-rightship-inspections"},{"code":"VET","title":"라이트십, 점검 선령기준 단계적 강화","src":"RightShip","date":"2026","kSum":"라이트십이 점검 선령기준을 14년에서 10년으로 4단계에 걸쳐 강화한다. 4월 12년+, 7월 11년+, 2027년 1월 10년+로 확대된다.","eSum":"RightShip is tightening its inspection age trigger from 14 to 10 years over four phases - 12+ in April, 11+ in July and 10+ from January 2027.","kImp":"선령기준 강화가 노후선 관리 부담을 키운다.","eImp":"Tighter age triggers raise the burden of managing older ships.","url":"https://rightship.com/insights/revised-rightship-inspection-age-trigger-what-means-owners-managers-charterers"},{"code":"VET","title":"트레이드윈즈: 라이트십, 벌커 점검규칙 재정비","src":"TradeWinds","date":"2026","kSum":"트레이드윈즈는 라이트십이 안전 제고와 오프하이어 비용 절감을 위해 벌커 점검규칙을 재정비했다고 보도했다. 선주·관리사·용선주 대응이 요구된다.","eSum":"TradeWinds reports RightShip has redrawn bulker inspection rules to boost safety and cut off-hire costs, requiring action from owners, managers and charterers.","kImp":"규칙 재정비가 운영비·상업성에 직접 영향을 준다.","eImp":"Redrawn rules directly affect opex and commercial standing.","url":"https://www.tradewindsnews.com/opinion/rightship-redraws-bulker-inspection-rules-to-boost-safety-and-cut-off-hire-costs/2-1-1720432"}]},{"code":"CLASS","type":"news","kTitle":"Section 14. Classification Societies","eTitle":"Section 14. Classification Societies","items":[{"code":"CLASS","title":"IACS 통일요건 E26/E27, 사이버복원력 적용 본격화","src":"IACS","date":"2026","kSum":"국제선급연합회(IACS)의 사이버복원력 통일요건 UR E26(선박 전체)·E27(선내 시스템·장비)이 2024년 7월 1일 이후 건조계약 신조선에 적용된다. 선급들은 설계·시운전 단계 검증을 강화하고 있다.","eSum":"IACS Unified Requirements UR E26 (ship) and E27 (onboard systems/equipment) on cyber resilience apply to newbuilds contracted on/after 1 July 2024, with classes tightening design- and trial-stage verification.","kImp":"사이버복원력이 신조 선급검사의 핵심 항목으로 부상한다.","eImp":"Cyber resilience becomes a core item in newbuild class survey.","url":"https://iacs.org.uk/news/iacs-ur-e26-and-e27-press-release"},{"code":"CLASS","title":"ClassNK, IACS UR E26 사이버복원력 가이드라인 발간","src":"ClassNK","date":"2026","kSum":"일본선급(ClassNK)이 IACS UR E26 요건을 설명하는 '선박 사이버복원력 가이드라인'을 발간했다. 요구 조치와 적합 절차를 정리해 선사·조선소의 이행을 지원한다.","eSum":"ClassNK released 'Guidelines for Cyber resilience of ships', explaining IACS UR E26 requirements and the actions needed, supporting owner/yard compliance.","kImp":"선급 가이드라인이 신조·기존선 사이버 적합을 견인한다.","eImp":"Class guidelines drive cyber compliance for new and existing ships.","url":"https://www.hellenicshippingnews.com/classnk-releases-guidelines-for-cyber-resilience-of-ships-explaining-iacs-ur-e26-requirements-and-necessary-actions/"},{"code":"CLASS","title":"DNV, 기술·규제 뉴스로 2026 규칙 개정 안내","src":"DNV","date":"2026","kSum":"DNV가 기술·규제 뉴스를 통해 2026년 선급규칙 개정과 발효 일정을 안내하고 있다. 구조·기관·디지털·연료 관련 요건 갱신이 신조·개조 설계에 반영된다.","eSum":"DNV's technical & regulatory news channel sets out 2026 class-rule amendments and entry-into-force dates, with structural, machinery, digital and fuel updates feeding into newbuild/retrofit design.","kImp":"규칙 개정 추적이 설계·검사 일정 관리에 필수다.","eImp":"Tracking rule changes is essential for design and survey scheduling.","url":"https://www.dnv.com/maritime/technical-regulatory-news/"},{"code":"CLASS","title":"DNV, 아네모이·GSI·하프니아 MR탱커 로터세일 AiP","src":"Bunker Index","date":"2026-06","kSum":"포시도니아 2026에서 아네모이(Anemoi)가 광저우조선(GSI)·하프니아(Hafnia)·DNV와 함께 접이식·방폭형 로터세일을 MR탱커 설계에 통합하는 공동개발을 마쳤고 DNV가 개념 AiP를 발급했다.","eSum":"At Posidonia 2026, Anemoi completed a JDP with GSI, Hafnia and DNV integrating folding, explosion-rated rotor sails into an MR tanker design, with DNV issuing an AiP.","kImp":"풍력보조 통합설계가 신조 탈탄소를 앞당긴다.","eImp":"Integrated wind-assist design advances newbuild decarbonization.","url":"https://www.bunkerindex.com/articles/article.php?a=22997&h=anemoi-and-partners-win-dnv-approval-in-principle-for-rotor-sail-integration-on-mr-tankers"},{"code":"CLASS","title":"DNV, 원자력 추진 컨테이너선 개념 승인","src":"SAFETY4SEA","date":"2026","kSum":"DNV가 원자력 추진 컨테이너선 개념설계에 승인을 부여했다. 차세대 무탄소 추진 옵션에 대한 선급 검토가 본격화되고 있다.","eSum":"DNV granted approval to a nuclear-powered container vessel concept, as class review of next-generation zero-carbon propulsion options gathers pace.","kImp":"원자력 추진 검토가 장기 탈탄소 옵션을 넓힌다.","eImp":"Nuclear-propulsion review broadens long-term decarbonization options.","url":"https://safety4sea.com/nuclear-powered-container-vessel-gets-approval-from-dnv/"},{"code":"CLASS","title":"뷰로베리타스, 암모니아 벙커링선 설계 AiP 부여","src":"SAFETY4SEA","date":"2026","kSum":"뷰로베리타스(Bureau Veritas)가 암모니아 벙커링선 설계에 AiP를 부여했다. 무탄소 연료 공급 인프라용 선박 설계 검증이 진전됐다.","eSum":"Bureau Veritas granted an AiP for an ammonia bunkering vessel design, advancing the validation of vessels for zero-carbon fuel-supply infrastructure.","kImp":"벙커링선 검증이 암모니아 공급망을 뒷받침한다.","eImp":"Bunker-vessel validation underpins the ammonia supply chain.","url":"https://safety4sea.com/bureau-veritas-grants-aip-for-ammonia-bunkering-vessel/"},{"code":"CLASS","title":"로이즈리스트, 2025 톱10 선급 발표…ABS 선두","src":"Lloyd's List","date":"2026","kSum":"로이즈리스트가 2025년 톱10 선급 순위를 발표했으며 ABS가 선두를 차지했다. 등록톤수·선대 구성·서비스 범위가 평가 기준이 됐다.","eSum":"Lloyd's List published its Top 10 classification societies 2025, with ABS taking the lead, ranked on tonnage, fleet composition and service scope.","kImp":"선급 순위가 선주의 선급 선택에 영향을 준다.","eImp":"Class rankings influence owners' choice of society.","url":"https://www.lloydslist.com/LL1155379/Top-10-classification-societies-2025"},{"code":"CLASS","title":"IIMS, 2025 톱10 선급 공개","src":"IIMS","date":"2026","kSum":"국제해사검정인협회(IIMS)가 2025년 톱10 선급을 공개했다. 안전·환경·디지털 역량이 선급 경쟁력의 핵심으로 평가됐다.","eSum":"The IIMS revealed the Top 10 classification societies for 2025, citing safety, environmental and digital capability as core competitive factors.","kImp":"역량 평가가 선급 서비스 차별화를 보여준다.","eImp":"Capability assessment highlights class service differentiation.","url":"https://www.iims.org.uk/top-10-classification-societies-in-2025-revealed/"},{"code":"CLASS","title":"마리타임사이프러스, 2025 톱10 선급 분석","src":"MaritimeCyprus","date":"2026","kSum":"마리타임사이프러스가 2025년 톱10 선급을 분석하며 ABS의 선두를 조명했다. 등록선대 규모와 친환경·디지털 서비스가 순위를 갈랐다.","eSum":"MaritimeCyprus analysed the Top 10 classification societies 2025, highlighting ABS's lead, with classed fleet size and green/digital services shaping the ranking.","kImp":"선급 경쟁구도가 신조·검사 시장에 영향을 준다.","eImp":"Class competition shapes the newbuild and survey markets.","url":"https://maritimecyprus.com/2025/12/07/top-10-classification-societies-2025-abs-takes-the-lead/"}]},{"code":"COMM","type":"news","kTitle":"Section 15. Commercial / Chartering Market","eTitle":"Section 15. Commercial / Chartering Market","items":[{"code":"COMM","title":"발틱운임지수, 케이프 주도로 반등","src":"Trading Economics","date":"2026-06","kSum":"발틱건화물운임지수(BDI)가 케이프사이즈 선형 강세에 힘입어 6월 12일 이후 최고치인 2,722선으로 반등했다. 다만 일부 세션에서는 전반적 약세도 혼재됐다.","eSum":"The Baltic Dry Index rebounded to around 2,722 - its highest since 12 June - led by the capesize segment, though some sessions showed broad-based weakness.","kImp":"대형선 강세가 건화물 시황 회복을 견인한다.","eImp":"Capesize strength leads the dry-bulk recovery.","url":"https://tradingeconomics.com/commodity/baltic"},{"code":"COMM","title":"드루리 주간 업데이트: 7월 관세 전 선적 앞당기기","src":"Drewry","date":"2026-06","kSum":"드루리 주간 컨테이너 업데이트에 따르면 7월 관세 변경 전 선적 앞당기기와 할증 도입으로 운임이 추가 상승했다. 향후 수주간 추가 상승이 전망된다.","eSum":"Drewry's weekly update notes rates rose further on front-loading ahead of July tariff changes and surcharge introductions, with more increases expected in coming weeks.","kImp":"관세 캘린더가 단기 운임 사이클을 좌우한다.","eImp":"The tariff calendar drives the short-term rate cycle.","url":"https://www.drewry.co.uk/supply-chain-advisors/world-container-index-weekly-update/container-shipping1"},{"code":"COMM","title":"드루리 결항 추적: 성수기 수급 관리 강화","src":"Drewry","date":"2026-06","kSum":"드루리 결항(blank sailing) 추적에 따르면 선사들이 성수기 수요와 공급 균형을 위해 결항을 조정하고 있다. 수급 관리가 운임 방어의 핵심 수단으로 활용된다.","eSum":"Drewry's cancelled-sailings tracker shows carriers adjusting blank sailings to balance peak-season demand and supply, using capacity management to defend rates.","kImp":"결항 운영이 운임 변동성을 조절한다.","eImp":"Blank-sailing management moderates rate volatility.","url":"https://www.drewry.co.uk/supply-chain-advisors/supply-chain-expertise/cancelled-sailings-tracker"},{"code":"COMM","title":"마스코트오션, 케이프사이즈 시장 진입","src":"Splash247","date":"2026","kSum":"마스코트오션(Mascot Ocean)이 케이프사이즈 시장에 진입했다. 대형 건화물선 수요 기대를 반영한 선대 확장 움직임이다.","eSum":"Mascot Ocean entered the capesize segment, a fleet-expansion move reflecting expectations of demand for large dry-bulk carriers.","kImp":"신규 진입이 대형선 시장 경쟁을 키운다.","eImp":"New entry adds competition in the large-bulker market.","url":"https://splash247.com/mascot-ocean-enters-the-cape-segment/"},{"code":"COMM","title":"로이즈리스트: VLCC 운임 재급등…호르무즈 혼선 지속","src":"Lloyd's List","date":"2026-06","kSum":"호르무즈 해협의 통항 혼선이 지속되며 VLCC 운임이 재차 급등했다. 재개 기대와 봉쇄 우려가 교차하며 운임 변동성이 극심하다.","eSum":"VLCC rates spiked yet again as confusion continued to reign at the Strait of Hormuz, with reopening hopes and closure fears whipsawing the market.","kImp":"통항 불확실성이 탱커 운임 변동성을 키운다.","eImp":"Transit uncertainty amplifies tanker-rate volatility.","url":"https://www.lloydslist.com/LL1157631/VLCC-rates-spike-yet-again-as-confusion-continues-to-reign-at-Strait-of-Hormuz"},{"code":"COMM","title":"로이즈리스트: 호르무즈 위기로 VLCC 물동량 36% 감소","src":"Lloyd's List","date":"2026-06","kSum":"호르무즈 위기로 VLCC 물동량이 36% 줄었으나 항해거리가 길어지며 톤마일은 유지되고 있다. 유효 선복 비효율이 운임을 떠받친다.","eSum":"The Hormuz crisis slashed VLCC volumes by 36%, but longer voyages sustained ton-mile demand; fleet inefficiency is propping up rates.","kImp":"톤마일 효과가 운임 하방을 방어한다.","eImp":"The ton-mile effect cushions rates against downside.","url":"https://www.lloydslist.com/LL1157100/Hormuz-crisis-slashes-VLCC-volumes-by-36-but-voyages-are-longer"},{"code":"COMM","title":"아르거스: VLCC 강세가 수에즈막스·아프라막스로 파급","src":"Argus Media","date":"2026","kSum":"아르거스는 VLCC 강세가 수에즈막스·아프라막스 운임을 끌어올릴 것으로 전망했다. 대형선 강세의 낙수효과가 중형 탱커로 확산된다.","eSum":"Argus expects the VLCC tide to lift Suezmax and Aframax rates, as strength in larger tankers spills into mid-size segments.","kImp":"선형 간 파급이 탱커 시장 전반을 끌어올린다.","eImp":"Cross-segment spillover lifts the whole tanker market.","url":"https://www.argusmedia.com/en/news-and-insights/latest-market-news/2771804-viewpoint-vlcc-tide-to-lift-suezmax-aframax-rates"},{"code":"COMM","title":"로드스타: 7월 인상 단행에 컨테이너 스폿운임 재상승","src":"The Loadstar","date":"2026-06","kSum":"선사들이 7월 운임 인상을 단행하면서 컨테이너 스폿운임이 재차 상승했다. 성수기 수요와 관세 전 선적이 인상을 뒷받침한다.","eSum":"Container spot rates surged again as carriers pushed through fresh July hikes, supported by peak-season demand and pre-tariff front-loading.","kImp":"연이은 인상이 단기 운임 사이클을 끌어올린다.","eImp":"Successive hikes drive the short-term rate cycle higher.","url":"https://theloadstar.com/spot-rates-surge-again-as-carriers-push-through-fresh-july-hikes/"},{"code":"COMM","title":"상하이 컨테이너운임지수(SCFI) 동향","src":"Container News","date":"2026-06","kSum":"상하이 컨테이너운임지수(SCFI)는 5월 평균 2,221선을 기록하며 강세 흐름을 보였다. 태평양·아시아-유럽 운임 상승이 지수를 끌어올렸다.","eSum":"The Shanghai Containerized Freight Index (SCFI) averaged around 2,221 in May, holding firm as Transpacific and Asia-Europe gains lifted the index.","kImp":"SCFI 강세가 컨테이너 시황 회복을 확인시킨다.","eImp":"A firm SCFI confirms the container-market recovery.","url":"https://container-news.com/scfi/"}]},{"code":"GEO","type":"news","kTitle":"Section 16. Geopolitical Chokepoints","eTitle":"Section 16. Geopolitical Chokepoints","items":[{"code":"GEO","title":"컨테이너 선사, 후티 위협에 홍해 우회 지속","src":"Seatrade Maritime","date":"2026","kSum":"컨테이너 선사들이 후티 위협을 피해 홍해를 우회하고 희망봉 항로를 유지하고 있다. 수에즈 정상화 시도는 시범적 수준에 머문다.","eSum":"Container lines continue rerouting from the Red Sea to avoid the Houthi threat, keeping the Cape of Good Hope route; Suez normalisation attempts remain tentative.","kImp":"우회 장기화가 톤마일·운임을 떠받친다.","eImp":"Prolonged rerouting supports ton-mile demand and rates.","url":"https://www.seatrade-maritime.com/containers/shipping-lines-reroute-from-red-sea-avoiding-houthi-threat"},{"code":"GEO","title":"수에즈 통항, 회복 시도에도 의문 남아","src":"AJOT","date":"2026","kSum":"수에즈 운하 통항이 일부 회복을 시도하고 있으나, 안보 불확실성으로 표준 항로로 복귀하기에는 의문이 남는다. 일부 대형 선사가 시범 통항에 나섰다.","eSum":"Suez Canal traffic is attempting a return, but security uncertainty leaves questions over restoring it as a standard corridor; some majors have begun trial transits.","kImp":"안보 변수에 따라 항로 선택이 반복적으로 바뀐다.","eImp":"Routing flips repeatedly with security conditions.","url":"https://www.ajot.com/insights/full/ai-suez-canal-traffic-returnswith-questions"},{"code":"GEO","title":"파나마운하, 엘니뇨 워치로 2026 수위 리스크","src":"Rio Times","date":"2026","kSum":"2026년 중반 엘니뇨 발생 가능성에 NOAA가 워치를 발령하면서, 중간 강도라도 파나마운하의 우기 수위 가용성이 빠듯해질 수 있다는 우려가 제기됐다.","eSum":"With NOAA issuing an El Nino Watch for mid-2026, even a moderate event could tighten Panama Canal water availability during the wet season.","kImp":"수위 리스크가 통항 슬롯·흘수 제한을 좌우한다.","eImp":"Water risk drives transit-slot and draft limits.","url":"https://www.riotimesonline.com/panama-canal-2026-guide/"},{"code":"GEO","title":"유조선 CEO: 합의 시 호르무즈 통항 급증 전망","src":"CNBC","date":"2026-06-11","kSum":"프론트라인 CEO는 미·이란 합의가 이뤄지면 호르무즈 통항이 빠르게 증가할 것이라고 전망했다. 통항 정상화 기대가 탱커 시황 심리를 자극한다.","eSum":"Frontline's CEO said Hormuz traffic would increase quickly if the US and Iran reached a deal, with normalisation hopes lifting tanker-market sentiment.","kImp":"합의 진전이 탱커 운임 기대를 좌우한다.","eImp":"Deal progress sways tanker-rate expectations.","url":"https://www.cnbc.com/2026/06/11/iran-strait-hormuz-oil-tanker-traffic-frontline.html"},{"code":"GEO","title":"UANI, 6월 4일 이란 전쟁 해운 업데이트","src":"UANI","date":"2026-06-04","kSum":"UANI는 6월 4일 이란 전쟁 관련 해운 동향 업데이트를 발표했다. 호르무즈 인근 정박 선박 군집과 우회 적재 동향을 정리했다.","eSum":"UANI issued an Iran War Shipping Update on 4 June, summarising clusters of vessels loitering near Hormuz and bypass-loading trends.","kImp":"감시 데이터가 위험·물류 판단의 근거가 된다.","eImp":"Monitoring data informs risk and logistics decisions.","url":"https://www.unitedagainstnucleariran.com/blog/iran-war-shipping-update-june-4-2026"},{"code":"GEO","title":"사우디 VLCC, 6월 호르무즈 통항 재개","src":"Discovery Alert","date":"2026-06","kSum":"사우디 VLCC들이 2026년 6월 호르무즈 해협 통항을 재개하며 걸프 원유 수출 정상화 신호를 보냈다. AIS 재가동과 통항 증가가 확인됐다.","eSum":"Saudi VLCCs resumed transiting the Strait of Hormuz in June 2026, signalling a normalisation of Gulf crude exports, with AIS reactivation and rising transits observed.","kImp":"걸프 수출 재개가 원유 물류를 재편한다.","eImp":"Resumed Gulf exports reshape crude logistics.","url":"https://discoveryalert.com.au/saudi-oil-tankers-strait-hormuz-shipping-resumption-2026/"},{"code":"GEO","title":"홍해·파나마 교란이 글로벌 항로 전략 재편","src":"Global Trade Magazine","date":"2026","kSum":"홍해와 파나마운하 교란이 글로벌 해운 항로 전략을 재편하고 있다. 선사들은 항로 다변화·재고 전략·운임 헤지로 대응하고 있다.","eSum":"Red Sea and Panama Canal disruptions are reshaping global shipping route strategies, with carriers responding via route diversification, inventory strategy and rate hedging.","kImp":"복수 길목 동시 교란이 공급망 복원력을 시험한다.","eImp":"Simultaneous chokepoint disruptions test supply-chain resilience.","url":"https://www.globaltrademag.com/the-impact-of-red-sea-and-panama-canal-disruptions-on-global-shipping-strategies/"},{"code":"GEO","title":"홍해·바브엘만데브, 후티 위협 재개·표적 확대","src":"The Ops Con","date":"2026-06-19","kSum":"후티의 홍해·바브엘만데브 위협이 재개되고 표적 논리가 확대됐다. 깃발뿐 아니라 이스라엘 연계 기업 선박이 표적이 되고 있다.","eSum":"The Houthi threat in the Red Sea and Bab el-Mandeb is back on with widened targeting logic - not just flag, but corporate links to Israel.","kImp":"표적 확대가 선사의 항로·기항 결정을 압박한다.","eImp":"Widened targeting pressures carriers' routing and port-call choices.","url":"https://theopscon.com/intelligence/red-sea-bab-el-mandeb-houthi-threat-marad-2026-006-19-jun-2026"},{"code":"GEO","title":"MARAD, 홍해·아덴만 후티 공격 해상경보 발령","src":"US MARAD","date":"2026-06","kSum":"미국 해사청(MARAD)이 홍해·바브엘만데브·아덴만·아라비아해·소말리아 분지에서 후티의 상선 공격 위협에 대한 해상경보(2026-006)를 발령했다.","eSum":"The US MARAD issued maritime advisory 2026-006 warning of Houthi attacks on commercial vessels across the Red Sea, Bab el-Mandeb, Gulf of Aden, Arabian Sea and Somali Basin.","kImp":"공식 경보가 위험구역 운항 의사결정에 반영된다.","eImp":"Official advisories inform high-risk-area transit decisions.","url":"https://www.maritime.dot.gov/msci/2026-006-red-sea-bab-el-mandeb-strait-gulf-aden-arabian-sea-and-somali-basin-houthi-attacks"}]},{"code":"TW","type":"news","kTitle":"Section 17. TradeWinds / Ship Management","eTitle":"Section 17. TradeWinds / Ship Management","items":[{"code":"TW","title":"BSM, 엘레나 판타지두 CPO 선임(6월 1일자)","src":"Bernhard Schulte SM","date":"2026-06","kSum":"베른하르트 슐테(Bernhard Schulte Shipmanagement)가 엘레나 판타지두(Elena Pantazidou)를 최고인사책임자(CPO)로 6월 1일자 선임했다. 인적자원 전략 강화 행보다.","eSum":"Bernhard Schulte Shipmanagement appointed Elena Pantazidou as Chief People Officer effective 1 June 2026, strengthening its HR strategy.","kImp":"인재 전략 강화가 대형 선박관리사 경쟁력의 축이다.","eImp":"People strategy is central to large ship-managers' competitiveness.","url":"https://www.bs-shipmanagement.com/media-centre/"},{"code":"TW","title":"선박관리 추가 합병 가능성 부상","src":"Splash247","date":"2026","kSum":"선박관리 업계에서 추가 합병 가능성이 부상하고 있다. 규모·디지털·연료전환 압력이 통합 논의를 촉진한다.","eSum":"Further consolidation is on the cards in ship management, with scale, digital and fuel-transition pressures fuelling merger talk.","kImp":"통합이 서비스 표준화와 투자여력을 키운다.","eImp":"Consolidation boosts standardisation and investment capacity.","url":"https://splash247.com/further-manager-mergers-on-the-cards/"},{"code":"TW","title":"2025 톱10 선박관리사 순위 발표","src":"Lloyd's List","date":"2026","kSum":"로이즈리스트가 2025년 톱10 선박관리사 순위를 발표했다. 관리 척수·선대 구성·서비스 범위가 평가 기준으로 작용했다.","eSum":"Lloyd's List published its Top 10 shipmanagers 2025 ranking, weighing managed ship counts, fleet composition and service scope.","kImp":"순위가 발주처·선주의 선택 기준에 영향을 준다.","eImp":"Rankings influence owners' and principals' selection criteria.","url":"https://www.lloydslist.com/LL1155778/Top-10-shipmanagers-2025"},{"code":"TW","title":"사모펀드, 선박관리 통합의 새 동력으로","src":"Splash247","date":"2026","kSum":"사모펀드(PE) 자본이 선박관리 통합의 새 동력으로 부상하고 있다. 인수·합병을 통한 규모 확대와 디지털 투자가 가속된다.","eSum":"Private equity is emerging as a new driver of ship-management consolidation, accelerating scale-building M&A and digital investment.","kImp":"PE 유입이 업계 구조와 서비스 모델을 바꾼다.","eImp":"PE inflows reshape industry structure and service models.","url":"https://splash247.com/private-equity-and-shipmanagement/"},{"code":"TW","title":"사모펀드의 선박관리 진입, 신뢰 논쟁 점화","src":"IndexBox","date":"2026","kSum":"사모펀드의 선박관리 진입을 둘러싸고 단기 수익 대 장기 신뢰의 논쟁이 2026년 업계에서 점화됐다. 선주·선원·화주의 신뢰 유지가 과제로 제시됐다.","eSum":"PE's role in ship management has ignited a 2026 industry debate over short-term gains versus long-term trust, with maintaining owner/crew/charterer trust flagged as a challenge.","kImp":"수익성과 신뢰의 균형이 통합 성패를 가른다.","eImp":"Balancing returns and trust will decide consolidation outcomes.","url":"https://www.indexbox.io/blog/private-equity-in-shipmanagement-short-term-gains-vs-long-term-trust/"},{"code":"TW","title":"앵글로이스턴, 오르카AI와 함대 도입 협력","src":"MarineLink","date":"2026","kSum":"앵글로이스턴(Anglo-Eastern)이 오르카AI(Orca AI)와 전략적 파트너십을 맺고 AI 기반 상황인지 플랫폼을 관리 선대에 도입한다. 대형 선박관리사의 첫 공식 AI 도입 약정이다.","eSum":"Anglo-Eastern partnered with Orca AI to roll out an AI-driven situational-awareness platform across its managed fleet - the first major ship-manager to formally commit to such adoption.","kImp":"AI 항법 지원이 기술관리 차별화 요소로 부상한다.","eImp":"AI navigation support becomes a technical-management differentiator.","url":"https://www.marinelink.com/news/maritime/technical-management"},{"code":"TW","title":"시너지마린그룹, 미디어센터 동향 업데이트","src":"Synergy Marine Group","date":"2026","kSum":"시너지마린그룹(Synergy Marine Group)이 선대 관리계약·리더십·친환경 프로젝트 등 최신 동향을 미디어센터를 통해 공개했다. 메탄올선 관리 확대와 합작 등을 추진 중이다.","eSum":"Synergy Marine Group's media centre details its latest fleet-management contracts, leadership and green projects, including expansion into methanol-ship management and joint ventures.","kImp":"대형 관리사의 사업 확장이 업계 표준을 끌어올린다.","eImp":"A major manager's expansion raises industry benchmarks.","url":"https://www.synergymarinegroup.com/media/5/"},{"code":"TW","title":"트레이드윈즈, 시너지마린그룹 동향 집중 보도","src":"TradeWinds","date":"2026","kSum":"트레이드윈즈가 시너지마린그룹의 관리계약·인사·기술도입 동향을 집중 보도하고 있다. 선박관리 시장의 통합·디지털화 흐름을 조명한다.","eSum":"TradeWinds is tracking Synergy Marine Group's management contracts, appointments and technology adoption, spotlighting consolidation and digitalisation in ship management.","kImp":"전문매체 보도가 관리사 경쟁구도를 가시화한다.","eImp":"Trade-press coverage clarifies the manager competitive landscape.","url":"https://www.tradewindsnews.com/tag/synergy_marine_group"},{"code":"TW","title":"트레이드윈즈 선박관리 섹션, 시장 동향 정리","src":"TradeWinds","date":"2026","kSum":"트레이드윈즈 선박관리 섹션이 관리사 인수·합병, 친환경 전환, 디지털화 등 최신 시장 동향을 정리하고 있다. 업계 재편이 가속되고 있다.","eSum":"TradeWinds' ship-management section rounds up the latest market trends - M&A, green transition and digitalisation - as industry restructuring accelerates.","kImp":"시장 동향 추적이 선주·관리사 전략에 활용된다.","eImp":"Trend tracking informs owner and manager strategy.","url":"https://www.tradewindsnews.com/ship_management"}]},{"code":"HOT","type":"news","kTitle":"Section 18. Lloyd's List Hot Topics (Strait of Hormuz)","eTitle":"Section 18. Lloyd's List Hot Topics (Strait of Hormuz)","items":[{"code":"HOT","title":"로이즈리스트: 그림자선단이 호르무즈 통항 주도","src":"Lloyd's List","date":"2026-06","kSum":"로이즈리스트는 이란이 우회 적재를 늘리면서 그림자선단(shadow fleet)이 호르무즈 통항을 주도하고 있다고 보도했다. 규정준수 선박은 위험으로 통항을 자제했다.","eSum":"Lloyd's List reports the shadow fleet dominated Hormuz crossings as Iran ramped up bypass loadings, while compliant ships held back due to risk.","kImp":"제재·위험이 통항 주체를 비규정 선박으로 이동시킨다.","eImp":"Sanctions and risk shift crossings toward non-compliant ships.","url":"https://www.lloydslist.com/LL1156563/Shadow-fleet-dominates-Hormuz-crossings-as-Iran-ramps-up-bypass-loadings"},{"code":"HOT","title":"로이즈리스트: 약 200척 규정준수 탱커 발 묶여","src":"Lloyd's List","date":"2026-06","kSum":"호르무즈 해협 봉쇄로 약 200척의 규정준수 탱커가 걸프에 발이 묶였다고 로이즈리스트가 전했다. 통항 동결이 원유 물류와 운임에 충격을 줬다.","eSum":"Lloyd's List reports around 200 compliant tankers were stranded as the Strait of Hormuz closure froze Gulf traffic, shocking crude logistics and rates.","kImp":"통항 동결이 톤마일·운임 변동성을 키운다.","eImp":"A transit freeze amplifies ton-mile and rate volatility.","url":"https://www.lloydslist.com/LL1156500/Around-200-compliant-tankers-stranded-as-Strait-of-Hormuz-closure-freezes-Gulf-traffic"},{"code":"HOT","title":"호르무즈 '다크 탱커' 통항 동향 2026","src":"Discovery Alert","date":"2026","kSum":"2026년 호르무즈 해협의 '다크 탱커(dark tanker)' 통항 동향이 분석됐다. AIS 비가동 선박의 우회 적재와 통항 패턴이 원유 시장에 영향을 준다.","eSum":"An analysis of dark-tanker traffic in the Strait of Hormuz in 2026 examines how AIS-off vessels' bypass loadings and transit patterns affect the oil market.","kImp":"비가시 선박 동향이 시장 투명성·리스크를 좌우한다.","eImp":"Opaque vessel flows drive market transparency and risk.","url":"https://discoveryalert.com.au/dark-tanker-traffic-strait-hormuz-oil-market-2026/"},{"code":"HOT","title":"2026 호르무즈 해협 위기 개관","src":"Wikipedia","date":"2026","kSum":"2026년 호르무즈 해협 위기는 2월 28일 미·이스라엘의 대이란 군사작전 이후 통항이 급감하며 시작됐다. 탱커 통항이 최대 70% 감소하고 150척 이상이 해협 밖에 정박했다.","eSum":"The 2026 Strait of Hormuz crisis began after the 28 February US/Israel operation against Iran, with tanker traffic falling up to 70% and 150+ ships anchoring outside the strait.","kImp":"위기 경과가 운임·보험·항로 전반을 규정한다.","eImp":"The crisis trajectory defines rates, insurance and routing.","url":"https://en.wikipedia.org/wiki/2026_Strait_of_Hormuz_crisis"},{"code":"HOT","title":"호르무즈 봉쇄로 VLCC 운임 사상 최고…시장 양분","src":"Breakbulk News","date":"2026-06","kSum":"호르무즈 봉쇄로 VLCC 운임이 사상 최고를 기록하며 운임 시장이 둘로 쪼개졌다. 걸프 진입 가능 선박과 그렇지 않은 선박 간 운임 격차가 극심하다.","eSum":"VLCC rates shattered all-time records as the Hormuz blockade split freight markets in two, with extreme rate gaps between ships that can enter the Gulf and those that cannot.","kImp":"봉쇄가 탱커 운임 구조를 왜곡시킨다.","eImp":"The blockade distorts the tanker-rate structure.","url":"https://breakbulk.news/vlcc-rates-shatter-all-time-records-as-hormuz-blockade-splits-freight-markets-in-two/"},{"code":"HOT","title":"Kpler: 호르무즈 봉쇄로 VLCC 운임 급등","src":"SAFETY4SEA","date":"2026-06","kSum":"Kpler 데이터에 따르면 호르무즈 해협 봉쇄로 VLCC 운임이 급등했다. 통항 동결과 정박 선박 군집이 유효 선복을 빠르게 줄였다.","eSum":"Per Kpler, the Strait of Hormuz shutdown sent VLCC rates soaring, as the transit freeze and loitering vessel clusters rapidly removed effective capacity.","kImp":"데이터 추적이 운임 급변의 근거를 제공한다.","eImp":"Data tracking explains the rate swings.","url":"https://safety4sea.com/kpler-hormuz-strait-shutdown-sends-vlcc-rates-soaring/"},{"code":"HOT","title":"무력화된 유조선, 美 발포 전 수십 차례 경고받아","src":"Washington Times (AP)","date":"2026-06-14","kSum":"AP 소식통에 따르면 미군이 발포하기 전 무력화된 유조선은 수십 차례 경고를 받았다. 봉쇄 집행을 둘러싼 사실관계 공방이 이어진다.","eSum":"Per an AP source, the disabled oil tanker received dozens of warnings before US forces opened fire, amid continuing disputes over the facts of blockade enforcement.","kImp":"집행 방식이 법적·안전 논쟁을 키운다.","eImp":"Enforcement methods fuel legal and safety disputes.","url":"https://www.washingtontimes.com/news/2026/jun/14/disabled-oil-tanker-received-dozens-warnings-us-opened-fire-ap-source/"},{"code":"HOT","title":"홍해 운송 위기 2026: 운임·우회·통항 분석","src":"Suaid Global","date":"2026","kSum":"홍해 운송 위기 2026 분석은 운임 상승·희망봉 우회·통항 감소를 종합했다. 아시아-유럽 운임이 위기 전比 25~40% 높은 수준을 유지한다.","eSum":"A Red Sea shipping crisis 2026 analysis covers higher rates, Cape diversions and reduced transits, with Asia-Europe rates 25-40% above pre-crisis levels.","kImp":"위기 장기화가 운임·리드타임을 구조적으로 높인다.","eImp":"A prolonged crisis structurally raises rates and lead times.","url":"https://suaidglobal.com/insights/red-sea-shipping-crisis-2026/"},{"code":"HOT","title":"예멘 인근서 상선 피습…후티 위협에 무장경비 대응","src":"The National","date":"2026-06-10","kSum":"후티 위협 속에서 예멘 바브엘만데브 인근을 항해하던 화물선이 소형정의 공격을 받았으나 무장경비가 격퇴했다. 이스라엘 연계 선박에 대한 표적이 이어진다.","eSum":"A cargo vessel was targeted by a small boat near Yemen's Bab el-Mandeb amid the Houthi threat, but armed guards fought off the attack.","kImp":"무장경비·회피기동이 피습 피해를 줄인다.","eImp":"Armed guards and evasive manoeuvres reduce attack damage.","url":"https://www.thenationalnews.com/news/2026/06/10/cargo-vessel-targeted-off-yemen-near-bab-al-mandeb-strait-after-houthi-threat/"}]}]};